[CmdletBinding()]
param(
    [Parameter(Mandatory = $true, Position = 0)]
    [uri] $ManifestUri
)

$ErrorActionPreference = 'Stop'
Set-StrictMode -Version 2.0

$script:ExtGuideEmbeddedResources = @{
    'en' = ''
    'zh-CN' = ''
    'zh-TW' = ''
}

$script:ExtGuideEmbeddedAssets = @{
    'chrome-extensions-page.png' = ''
    'chrome-extensions-page.zh-TW.png' = ''
}

function New-ExtGuideException {
    param(
        [Parameter(Mandatory = $true)]
        [ValidateSet('Configuration', 'Network', 'Integrity', 'Destination', 'Extraction', 'ChromeDiscovery', 'ExecutableValidation', 'Launch', 'Policy')]
        [string] $Category,
        [Parameter(Mandatory = $true)][string] $Message,
        [Parameter(Mandatory = $true)][string] $Recovery,
        [System.Exception] $InnerException
    )

    $exception = New-Object System.Exception($Message, $InnerException)
    $exception.Data['ExtGuideCategory'] = $Category
    $exception.Data['ExtGuideRecovery'] = $Recovery
    return $exception
}

function Throw-ExtGuideError {
    param(
        [Parameter(Mandatory = $true)][string] $Category,
        [Parameter(Mandatory = $true)][string] $Message,
        [Parameter(Mandatory = $true)][string] $Recovery,
        [System.Exception] $InnerException
    )

    throw (New-ExtGuideException -Category $Category -Message $Message -Recovery $Recovery -InnerException $InnerException)
}

function ConvertTo-ExtGuideFailure {
    param([Parameter(Mandatory = $true)][System.Management.Automation.ErrorRecord] $ErrorRecord)

    $category = [string] $ErrorRecord.Exception.Data['ExtGuideCategory']
    $recovery = [string] $ErrorRecord.Exception.Data['ExtGuideRecovery']
    if ([string]::IsNullOrWhiteSpace($category)) { $category = 'Configuration' }
    if ([string]::IsNullOrWhiteSpace($recovery)) { $recovery = 'Review the installer manifest and try again.' }

    return [pscustomobject]@{
        Status = 'Failed'
        Category = $category
        Message = $ErrorRecord.Exception.Message
        Recovery = $recovery
    }
}


function Test-ExtGuideSafeName {
    param([string] $Value)

    if ([string]::IsNullOrWhiteSpace($Value) -or $Value.Length -gt 64) { return $false }
    if ($Value -in @('.', '..') -or $Value -ne $Value.Trim()) { return $false }
    if ($Value.IndexOfAny([System.IO.Path]::GetInvalidFileNameChars()) -ge 0) { return $false }
    return $Value -match '^[\p{L}\p{N}][\p{L}\p{N} ._-]*$'
}

function Test-ExtGuideRelativePath {
    param([string] $Value)

    if ([string]::IsNullOrWhiteSpace($Value) -or [System.IO.Path]::IsPathRooted($Value)) { return $false }
    if ($Value -match ':' -or $Value -match '(^|[\\/])\.\.([\\/]|$)') { return $false }
    return $true
}

function ConvertFrom-ExtGuideManifest {
    param([Parameter(Mandatory = $true)][string] $Json)

    try { $manifest = $Json | ConvertFrom-Json -ErrorAction Stop }
    catch {
        Throw-ExtGuideError -Category 'Configuration' -Message 'The installer manifest is not valid JSON.' -Recovery 'Ask the extension publisher to publish a valid versioned installer manifest.' -InnerException $_.Exception
    }

    foreach ($propertyName in @('schemaVersion', 'displayName', 'publisher', 'installFolderName', 'archiveUrl', 'extensionRoot')) {
        if ($null -eq $manifest.PSObject.Properties[$propertyName] -or [string]::IsNullOrWhiteSpace([string] $manifest.$propertyName)) {
            Throw-ExtGuideError -Category 'Configuration' -Message "The installer manifest is missing '$propertyName'." -Recovery 'Ask the extension publisher to correct the installer manifest.'
        }
    }
    if ([int] $manifest.schemaVersion -ne 1) {
        Throw-ExtGuideError -Category 'Configuration' -Message "Installer manifest schema version '$($manifest.schemaVersion)' is not supported." -Recovery 'Use an ExtGuide release that supports this schema, or ask the publisher to use schema version 1.'
    }
    foreach ($propertyName in @('publisher', 'installFolderName')) {
        if (-not (Test-ExtGuideSafeName -Value ([string] $manifest.$propertyName))) {
            Throw-ExtGuideError -Category 'Configuration' -Message "The manifest value '$propertyName' is not a safe folder name." -Recovery 'Ask the extension publisher to use a short name without path separators or reserved characters.'
        }
    }
    if ($null -ne $manifest.PSObject.Properties['integrationId'] -and
        -not [string]::IsNullOrWhiteSpace([string] $manifest.integrationId) -and
        [string] $manifest.integrationId -notmatch '^[A-Za-z0-9][A-Za-z0-9._-]{2,127}$') {
        Throw-ExtGuideError -Category 'Configuration' -Message "The manifest value 'integrationId' is not a safe identifier." -Recovery 'Ask the publisher to use 3-128 letters, numbers, dots, underscores, or hyphens.'
    }
    if ($null -ne $manifest.PSObject.Properties['extensionVersion'] -and
        -not [string]::IsNullOrWhiteSpace([string] $manifest.extensionVersion) -and
        [string] $manifest.extensionVersion -notmatch '^\d+(\.\d+){0,3}$') {
        Throw-ExtGuideError -Category 'Configuration' -Message "The manifest value 'extensionVersion' is not a valid Chrome extension version." -Recovery 'Ask the publisher to use one to four dot-separated numeric components.'
    }
    if (-not (Test-ExtGuideRelativePath -Value ([string] $manifest.extensionRoot))) {
        Throw-ExtGuideError -Category 'Configuration' -Message 'The extension root must be a relative path inside the release archive.' -Recovery 'Ask the extension publisher to correct extensionRoot.'
    }
    foreach ($urlProperty in @('archiveUrl', 'sha256Url')) {
        if ($null -eq $manifest.PSObject.Properties[$urlProperty] -or [string]::IsNullOrWhiteSpace([string] $manifest.$urlProperty)) { continue }
        $uri = $null
        if (-not [uri]::TryCreate([string] $manifest.$urlProperty, [System.UriKind]::Absolute, [ref] $uri) -or $uri.Scheme -ne 'https') {
            Throw-ExtGuideError -Category 'Configuration' -Message "The manifest value '$urlProperty' must be an absolute HTTPS URL." -Recovery 'Ask the extension publisher to use a direct HTTPS release asset URL.'
        }
    }

    $inlineDigest = if ($null -ne $manifest.PSObject.Properties['sha256']) { [string] $manifest.sha256 } else { '' }
    $digestUrl = if ($null -ne $manifest.PSObject.Properties['sha256Url']) { [string] $manifest.sha256Url } else { '' }
    if ([string]::IsNullOrWhiteSpace($inlineDigest) -eq [string]::IsNullOrWhiteSpace($digestUrl)) {
        Throw-ExtGuideError -Category 'Configuration' -Message 'The manifest must declare exactly one SHA-256 digest or SHA-256 URL.' -Recovery 'Ask the extension publisher to provide either sha256 or sha256Url.'
    }
    if (-not [string]::IsNullOrWhiteSpace($inlineDigest) -and $inlineDigest -notmatch '^[a-fA-F0-9]{64}$') {
        Throw-ExtGuideError -Category 'Configuration' -Message 'The manifest SHA-256 digest is malformed.' -Recovery 'Ask the extension publisher to publish a 64-character hexadecimal SHA-256 digest.'
    }
    return $manifest
}

function Get-ExtGuideIntegrationId {
    param([Parameter(Mandatory = $true)] $Manifest)

    if ($null -ne $Manifest.PSObject.Properties['integrationId'] -and -not [string]::IsNullOrWhiteSpace([string] $Manifest.integrationId)) {
        return [string] $Manifest.integrationId
    }
    return ([string] $Manifest.publisher + '|' + [string] $Manifest.installFolderName)
}

function ConvertFrom-ExtGuideDigestText {
    param([string] $Text)

    $match = [regex]::Match($Text, '(?i)(?<![a-f0-9])[a-f0-9]{64}(?![a-f0-9])')
    if (-not $match.Success) {
        Throw-ExtGuideError -Category 'Integrity' -Message 'The downloaded SHA-256 file does not contain a valid digest.' -Recovery 'Ask the extension publisher to repair the digest asset before retrying.'
    }
    return $match.Value.ToLowerInvariant()
}


function Get-ExtGuideSha256 {
    param([Parameter(Mandatory = $true)][byte[]] $Bytes)

    $sha256 = [System.Security.Cryptography.SHA256]::Create()
    try { return -join ($sha256.ComputeHash($Bytes) | ForEach-Object { $_.ToString('x2') }) }
    finally { $sha256.Dispose() }
}

function Test-ExtGuideDestinationWritable {
    param([Parameter(Mandatory = $true)][string] $Destination)

    $probeDirectory = if (Test-Path -LiteralPath $Destination -PathType Container) { $Destination } else { Split-Path -Parent $Destination }
    try {
        $null = New-Item -ItemType Directory -Path $probeDirectory -Force -ErrorAction Stop
        $probe = Join-Path $probeDirectory ('.extguide-write-' + [guid]::NewGuid().ToString('N'))
        [System.IO.File]::WriteAllText($probe, 'ExtGuide write probe')
        Remove-Item -LiteralPath $probe -Force -ErrorAction Stop
        return $true
    }
    catch { return $false }
}

function Expand-ExtGuideArchiveSafely {
    param(
        [Parameter(Mandatory = $true)][byte[]] $ArchiveBytes,
        [Parameter(Mandatory = $true)][string] $StagingDirectory
    )

    Add-Type -AssemblyName System.IO.Compression -ErrorAction Stop
    $memory = New-Object System.IO.MemoryStream(, $ArchiveBytes)
    $archive = $null
    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $stagingRoot = [System.IO.Path]::GetFullPath($StagingDirectory).TrimEnd('\') + '\'
    try {
        $archive = New-Object System.IO.Compression.ZipArchive($memory, [System.IO.Compression.ZipArchiveMode]::Read)
        foreach ($entry in $archive.Entries) {
            $entryPath = $entry.FullName.Replace('/', '\')
            $unixMode = (($entry.ExternalAttributes -shr 16) -band 0xF000)
            if ($unixMode -eq 0xA000) {
                Throw-ExtGuideError -Category 'Extraction' -Message 'The extension archive contains a symbolic link, which is not supported.' -Recovery 'Ask the publisher to provide a regular-file-only archive.'
            }
            if ([string]::IsNullOrWhiteSpace($entryPath)) { continue }
            if ([System.IO.Path]::IsPathRooted($entryPath) -or $entryPath -match ':' -or $entryPath -match '(^|\\)\.\.(\\|$)') {
                Throw-ExtGuideError -Category 'Extraction' -Message 'The extension archive contains an entry outside the selected installation directory.' -Recovery 'Do not install this archive; ask the publisher to remove unsafe paths.'
            }
            $targetPath = [System.IO.Path]::GetFullPath((Join-Path $StagingDirectory $entryPath))
            if (-not $targetPath.StartsWith($stagingRoot, [System.StringComparison]::OrdinalIgnoreCase)) {
                Throw-ExtGuideError -Category 'Extraction' -Message 'The extension archive contains an escaping path.' -Recovery 'Do not install this archive; ask the publisher to rebuild it safely.'
            }
            if (-not $seen.Add($targetPath)) {
                Throw-ExtGuideError -Category 'Extraction' -Message 'The extension archive contains duplicate or conflicting entries.' -Recovery 'Ask the publisher to remove duplicate archive entries.'
            }
            if ($entry.FullName.EndsWith('/')) {
                $null = New-Item -ItemType Directory -Path $targetPath -Force
                continue
            }
            $parent = Split-Path -Parent $targetPath
            $null = New-Item -ItemType Directory -Path $parent -Force
            $source = $entry.Open()
            $destinationStream = $null
            try {
                $destinationStream = New-Object System.IO.FileStream($targetPath, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
                $source.CopyTo($destinationStream)
            }
            finally {
                if ($null -ne $destinationStream) { $destinationStream.Dispose() }
                $source.Dispose()
            }
        }
    }
    catch {
        if ($null -ne $_.Exception.Data['ExtGuideCategory']) { throw }
        Throw-ExtGuideError -Category 'Extraction' -Message 'The downloaded extension archive is corrupt or unsupported.' -Recovery 'Retry the download; if it fails again, ask the publisher to replace the archive.' -InnerException $_.Exception
    }
    finally {
        if ($null -ne $archive) { $archive.Dispose() }
        $memory.Dispose()
    }
}

function Get-ExtGuideExtensionManifest {
    param(
        [Parameter(Mandatory = $true)][string] $ExtensionDirectory,
        [string] $Category = 'Extraction'
    )

    $manifestPath = Join-Path $ExtensionDirectory 'manifest.json'
    if (-not (Test-Path -LiteralPath $manifestPath -PathType Leaf)) {
        Throw-ExtGuideError -Category $Category -Message 'The extension root does not contain manifest.json.' -Recovery 'Choose the correct existing installation or ask the publisher to rebuild the release archive.'
    }
    try { $manifest = Get-Content -LiteralPath $manifestPath -Raw | ConvertFrom-Json -ErrorAction Stop }
    catch {
        Throw-ExtGuideError -Category $Category -Message 'The Chrome extension manifest is not valid JSON.' -Recovery 'Choose the correct existing installation or ask the publisher to ship a valid prebuilt extension.' -InnerException $_.Exception
    }
    if ([int] $manifest.manifest_version -ne 3 -or [string]::IsNullOrWhiteSpace([string] $manifest.name) -or [string]::IsNullOrWhiteSpace([string] $manifest.version)) {
        Throw-ExtGuideError -Category $Category -Message 'The files are not a valid prebuilt Manifest V3 extension.' -Recovery 'Choose the correct existing installation or ask the publisher to include a complete built extension.'
    }
    return $manifest
}

function Get-ExtGuideUpdateJournalPath {
    param([Parameter(Mandatory = $true)][string] $Destination)
    $fullDestination = [System.IO.Path]::GetFullPath($Destination)
    return Join-Path (Split-Path -Parent $fullDestination) ('.' + (Split-Path -Leaf $fullDestination) + '.extguide-update.json')
}

function Write-ExtGuideUpdateJournal {
    param([Parameter(Mandatory = $true)][string] $Path, [Parameter(Mandatory = $true)] $Journal)

    $temporary = $Path + '.tmp-' + [guid]::NewGuid().ToString('N')
    try {
        [System.IO.File]::WriteAllText($temporary, ($Journal | ConvertTo-Json -Depth 5), (New-Object System.Text.UTF8Encoding($true)))
        Move-Item -LiteralPath $temporary -Destination $Path -Force -ErrorAction Stop
    }
    finally {
        if (Test-Path -LiteralPath $temporary -PathType Leaf) { Remove-Item -LiteralPath $temporary -Force -ErrorAction SilentlyContinue }
    }
}

function Test-ExtGuideTransactionPath {
    param([Parameter(Mandatory = $true)][string] $Path, [Parameter(Mandatory = $true)][string] $Parent, [Parameter(Mandatory = $true)][string] $Leaf, [Parameter(Mandatory = $true)][string] $Kind)

    try { $fullPath = [System.IO.Path]::GetFullPath($Path) } catch { return $false }
    $expectedParent = [System.IO.Path]::GetFullPath($Parent).TrimEnd('\')
    if (-not (Split-Path -Parent $fullPath).Equals($expectedParent, [System.StringComparison]::OrdinalIgnoreCase)) { return $false }
    return (Split-Path -Leaf $fullPath) -match ('^\.' + [regex]::Escape($Leaf) + '\.extguide-' + $Kind + '-[0-9a-f]{32}$')
}

function Repair-ExtGuideInterruptedUpdate {
    param([Parameter(Mandatory = $true)][string] $Destination)

    $fullDestination = [System.IO.Path]::GetFullPath($Destination)
    $journalPath = Get-ExtGuideUpdateJournalPath -Destination $fullDestination
    if (-not (Test-Path -LiteralPath $journalPath -PathType Leaf)) { return $false }
    try { $journal = Get-Content -LiteralPath $journalPath -Raw | ConvertFrom-Json -ErrorAction Stop }
    catch {
        Throw-ExtGuideError -Category 'Destination' -Message 'ExtGuide found a damaged update recovery record.' -Recovery 'Do not delete extension files. Ask the publisher or administrator to inspect the ExtGuide update files beside the installation.' -InnerException $_.Exception
    }

    $recordedDestination = [System.IO.Path]::GetFullPath([string] $journal.Destination)
    $parent = Split-Path -Parent $fullDestination
    $leaf = Split-Path -Leaf $fullDestination
    if (-not $recordedDestination.Equals($fullDestination, [System.StringComparison]::OrdinalIgnoreCase) -or
        -not (Test-ExtGuideTransactionPath -Path ([string] $journal.Staging) -Parent $parent -Leaf $leaf -Kind 'stage') -or
        -not (Test-ExtGuideTransactionPath -Path ([string] $journal.Backup) -Parent $parent -Leaf $leaf -Kind 'backup')) {
        Throw-ExtGuideError -Category 'Destination' -Message 'ExtGuide rejected an unsafe update recovery record.' -Recovery 'Ask the publisher or administrator to inspect the installation directory.'
    }

    $staging = [string] $journal.Staging
    $backup = [string] $journal.Backup
    $destinationExists = Test-Path -LiteralPath $fullDestination -PathType Container
    $backupExists = Test-Path -LiteralPath $backup -PathType Container
    $stagingExists = Test-Path -LiteralPath $staging -PathType Container

    if (-not $destinationExists -and $backupExists) {
        Move-Item -LiteralPath $backup -Destination $fullDestination -ErrorAction Stop
        $destinationExists = $true
        $backupExists = $false
    }
    elseif (-not $destinationExists -and -not $backupExists -and $stagingExists) {
        Move-Item -LiteralPath $staging -Destination $fullDestination -ErrorAction Stop
        $destinationExists = $true
        $stagingExists = $false
    }

    if ($destinationExists -and $backupExists) { Remove-Item -LiteralPath $backup -Recurse -Force -ErrorAction Stop }
    if ($destinationExists -and $stagingExists) { Remove-Item -LiteralPath $staging -Recurse -Force -ErrorAction Stop }
    Remove-Item -LiteralPath $journalPath -Force -ErrorAction Stop
    return $true
}

function Read-ExtGuideInstallationReceipt {
    param([Parameter(Mandatory = $true)][string] $Destination)

    $path = Join-Path $Destination '.extguide-install.json'
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { return $null }
    try { return Get-Content -LiteralPath $path -Raw | ConvertFrom-Json -ErrorAction Stop }
    catch {
        Throw-ExtGuideError -Category 'Destination' -Message 'The existing ExtGuide installation receipt is damaged.' -Recovery 'Choose another folder or ask the publisher to inspect the existing installation.' -InnerException $_.Exception
    }
}

function Install-ExtGuideArchive {
    param(
        [Parameter(Mandatory = $true)][byte[]] $ArchiveBytes,
        [Parameter(Mandatory = $true)][string] $Destination,
        [Parameter(Mandatory = $true)][string] $ExtensionRoot,
        [string] $IntegrationId,
        [string] $Publisher,
        [string] $InstallFolderName,
        [string] $ArchiveSha256,
        [string] $ExpectedVersion
    )

    $Destination = [System.IO.Path]::GetFullPath($Destination)
    $null = New-Item -ItemType Directory -Path (Split-Path -Parent $Destination) -Force -ErrorAction Stop
    $null = Repair-ExtGuideInterruptedUpdate -Destination $Destination
    $parent = Split-Path -Parent $Destination
    $leaf = Split-Path -Leaf $Destination
    $staging = Join-Path $parent ('.' + $leaf + '.extguide-stage-' + [guid]::NewGuid().ToString('N'))
    $backup = Join-Path $parent ('.' + $leaf + '.extguide-backup-' + [guid]::NewGuid().ToString('N'))
    $journalPath = Get-ExtGuideUpdateJournalPath -Destination $Destination
    $movedCurrent = $false
    $installed = $false
    $wasUpdate = Test-Path -LiteralPath $Destination
    $previousVersion = $null
    try {
        $null = New-Item -ItemType Directory -Path $staging -Force -ErrorAction Stop
        Expand-ExtGuideArchiveSafely -ArchiveBytes $ArchiveBytes -StagingDirectory $staging
        $stagedExtensionRoot = [System.IO.Path]::GetFullPath((Join-Path $staging $ExtensionRoot))
        $extensionManifest = Get-ExtGuideExtensionManifest -ExtensionDirectory $stagedExtensionRoot
        if (-not [string]::IsNullOrWhiteSpace($ExpectedVersion) -and [string] $extensionManifest.version -ne $ExpectedVersion) {
            Throw-ExtGuideError -Category 'Integrity' -Message 'The extension version inside the archive does not match the installer manifest.' -Recovery 'Do not install this archive; ask the publisher to correct the release metadata.'
        }
        if ($wasUpdate) {
            $existingRoot = [System.IO.Path]::GetFullPath((Join-Path $Destination $ExtensionRoot))
            $existingManifest = Get-ExtGuideExtensionManifest -ExtensionDirectory $existingRoot -Category 'Destination'
            $previousVersion = [string] $existingManifest.version
            $receipt = Read-ExtGuideInstallationReceipt -Destination $Destination
            if ($null -ne $receipt) {
                if ([int] $receipt.receiptVersion -ne 1 -or
                    [string] $receipt.integrationId -ne $IntegrationId -or
                    [string] $receipt.extensionRoot -ne $ExtensionRoot) {
                    Throw-ExtGuideError -Category 'Destination' -Message 'The selected folder belongs to a different ExtGuide installation.' -Recovery 'Choose the folder previously used for this extension, or choose a new location.'
                }
            }
            elseif (-not ([string] $existingManifest.name).Equals([string] $extensionManifest.name, [System.StringComparison]::Ordinal)) {
                Throw-ExtGuideError -Category 'Destination' -Message 'The selected folder contains a different unpacked extension.' -Recovery 'Choose the folder previously used for this extension, or choose a new location.'
            }
        }

        if (-not [string]::IsNullOrWhiteSpace($IntegrationId)) {
            $receiptPayload = [ordered]@{
                receiptVersion = 1
                integrationId = $IntegrationId
                publisher = $Publisher
                installFolderName = $InstallFolderName
                extensionRoot = $ExtensionRoot
                extensionVersion = [string] $extensionManifest.version
                archiveSha256 = $ArchiveSha256
            }
            [System.IO.File]::WriteAllText((Join-Path $staging '.extguide-install.json'), ($receiptPayload | ConvertTo-Json -Depth 4), (New-Object System.Text.UTF8Encoding($true)))
        }

        $journal = [ordered]@{ journalVersion = 1; Destination = $Destination; Staging = $staging; Backup = $backup; Phase = 'Prepared' }
        Write-ExtGuideUpdateJournal -Path $journalPath -Journal $journal
        if ($wasUpdate) {
            Move-Item -LiteralPath $Destination -Destination $backup -ErrorAction Stop
            $movedCurrent = $true
            $journal.Phase = 'OldBackedUp'
            Write-ExtGuideUpdateJournal -Path $journalPath -Journal $journal
        }
        Move-Item -LiteralPath $staging -Destination $Destination -ErrorAction Stop
        $installed = $true
        $journal.Phase = 'NewActivated'
        Write-ExtGuideUpdateJournal -Path $journalPath -Journal $journal
        if ($movedCurrent -and (Test-Path -LiteralPath $backup)) {
            Remove-Item -LiteralPath $backup -Recurse -Force -ErrorAction SilentlyContinue
            $movedCurrent = $false
        }
        Remove-Item -LiteralPath $journalPath -Force -ErrorAction SilentlyContinue
        $installedRoot = [System.IO.Path]::GetFullPath((Join-Path $Destination $ExtensionRoot))
        $content = @{}
        Get-ChildItem -LiteralPath $installedRoot -File -Recurse | ForEach-Object {
            $relative = $_.FullName.Substring($installedRoot.Length).TrimStart('\')
            $content[$relative] = $_.Length
        }
        return [pscustomobject]@{ ExtensionRoot = $installedRoot; Content = $content; WasUpdate = $wasUpdate; PreviousVersion = $previousVersion; InstalledVersion = [string] $extensionManifest.version }
    }
    catch {
        if ($movedCurrent -and -not (Test-Path -LiteralPath $Destination) -and (Test-Path -LiteralPath $backup)) {
            try { Move-Item -LiteralPath $backup -Destination $Destination -ErrorAction Stop } catch { }
            $movedCurrent = $false
        }
        if (-not $movedCurrent -and (Test-Path -LiteralPath $Destination) -and (Test-Path -LiteralPath $journalPath)) {
            Remove-Item -LiteralPath $journalPath -Force -ErrorAction SilentlyContinue
        }
        if ($null -ne $_.Exception.Data['ExtGuideCategory']) { throw }
        Throw-ExtGuideError -Category 'Destination' -Message 'ExtGuide could not replace the current installation safely.' -Recovery 'Close Chrome and any program using the extension files, then retry. The previous installation was preserved.' -InnerException $_.Exception
    }
    finally {
        if (-not $installed -and (Test-Path -LiteralPath $staging)) { Remove-Item -LiteralPath $staging -Recurse -Force -ErrorAction SilentlyContinue }
        if ($movedCurrent -and (Test-Path -LiteralPath $backup) -and (Test-Path -LiteralPath $Destination)) { Remove-Item -LiteralPath $backup -Recurse -Force -ErrorAction SilentlyContinue }
    }
}


function Initialize-ExtGuideNativePathMethods {
    if ('ExtGuide.NativePathMethods' -as [type]) { return }

    Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
using Microsoft.Win32.SafeHandles;

namespace ExtGuide {
    public static class NativePathMethods {
        [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
        public static extern SafeFileHandle CreateFile(
            string fileName,
            uint desiredAccess,
            uint shareMode,
            IntPtr securityAttributes,
            uint creationDisposition,
            uint flagsAndAttributes,
            IntPtr templateFile);

        [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
        public static extern uint GetFinalPathNameByHandle(
            SafeFileHandle file,
            System.Text.StringBuilder path,
            uint pathLength,
            uint flags);
    }
}
'@
}

function ConvertFrom-ExtGuideDevicePath {
    param([Parameter(Mandatory = $true)][string] $Path)

    if ($Path.StartsWith('\\?\UNC\', [System.StringComparison]::OrdinalIgnoreCase)) {
        return '\\' + $Path.Substring(8)
    }
    if ($Path.StartsWith('\\?\', [System.StringComparison]::OrdinalIgnoreCase)) {
        return $Path.Substring(4)
    }
    return $Path
}

function Get-ExtGuideFinalPath {
    param([Parameter(Mandatory = $true)][string] $Path)

    Initialize-ExtGuideNativePathMethods
    $fullPath = [System.IO.Path]::GetFullPath($Path)
    $flags = if (Test-Path -LiteralPath $fullPath -PathType Container) { [uint32] 0x02000000 } else { [uint32] 0x00000080 }
    $handle = [ExtGuide.NativePathMethods]::CreateFile($fullPath, 0, 7, [IntPtr]::Zero, 3, $flags, [IntPtr]::Zero)
    try {
        if ($handle.IsInvalid) {
            throw "CreateFile failed for '$fullPath': $([Runtime.InteropServices.Marshal]::GetLastWin32Error())"
        }
        $buffer = New-Object System.Text.StringBuilder 32768
        $length = [ExtGuide.NativePathMethods]::GetFinalPathNameByHandle($handle, $buffer, $buffer.Capacity, 0)
        if ($length -eq 0) {
            throw "GetFinalPathNameByHandle failed for '$fullPath': $([Runtime.InteropServices.Marshal]::GetLastWin32Error())"
        }
        return ConvertFrom-ExtGuideDevicePath -Path $buffer.ToString()
    }
    finally {
        $handle.Dispose()
    }
}

function Test-ExtGuidePathVirtualized {
    param([Parameter(Mandatory = $true)][string] $Destination)

    $parent = Split-Path -Parent ([System.IO.Path]::GetFullPath($Destination))
    $null = New-Item -ItemType Directory -Path $parent -Force -ErrorAction Stop
    $probePath = Join-Path $parent ('.extguide-path-' + [guid]::NewGuid().ToString('N') + '.tmp')
    try {
        [System.IO.File]::WriteAllText($probePath, 'ExtGuide path probe')
        $requestedPath = [System.IO.Path]::GetFullPath($probePath)
        $finalPath = Get-ExtGuideFinalPath -Path $probePath
        return -not $requestedPath.Equals($finalPath, [System.StringComparison]::OrdinalIgnoreCase)
    }
    finally {
        if (Test-Path -LiteralPath $probePath -PathType Leaf) {
            Remove-Item -LiteralPath $probePath -Force -ErrorAction SilentlyContinue
        }
    }
}

function Get-ExtGuideInstallWorkerSource {
    $parts = @(
        @'
[CmdletBinding()]
param([Parameter(Mandatory = $true)][string] $JobPath)

$ErrorActionPreference = 'Stop'
Set-StrictMode -Version 2.0
'@
    )
    foreach ($functionName in @(
        'New-ExtGuideException',
        'Throw-ExtGuideError',
        'Get-ExtGuideSha256',
        'Expand-ExtGuideArchiveSafely',
        'Get-ExtGuideExtensionManifest',
        'Get-ExtGuideUpdateJournalPath',
        'Write-ExtGuideUpdateJournal',
        'Test-ExtGuideTransactionPath',
        'Repair-ExtGuideInterruptedUpdate',
        'Read-ExtGuideInstallationReceipt',
        'Install-ExtGuideArchive'
    )) {
        $definition = (Get-Command -Name $functionName -CommandType Function -ErrorAction Stop).Definition
        $parts += "function $functionName {`r`n$definition`r`n}"
    }
    $parts += @'
$job = Get-Content -LiteralPath $JobPath -Raw | ConvertFrom-Json -ErrorAction Stop
try {
    [byte[]] $archiveBytes = [System.IO.File]::ReadAllBytes([string] $job.ArchivePath)
    if ((Get-ExtGuideSha256 -Bytes $archiveBytes) -ne [string] $job.ArchiveSha256) {
        Throw-ExtGuideError -Category 'Integrity' -Message 'The elevated installer received archive bytes that do not match the verified digest.' -Recovery 'Cancel the installation and run ExtGuide again.'
    }
    $installation = Install-ExtGuideArchive `
        -ArchiveBytes $archiveBytes `
        -Destination ([string] $job.Destination) `
        -ExtensionRoot ([string] $job.ExtensionRoot) `
        -IntegrationId ([string] $job.IntegrationId) `
        -Publisher ([string] $job.Publisher) `
        -InstallFolderName ([string] $job.InstallFolderName) `
        -ArchiveSha256 ([string] $job.ArchiveSha256) `
        -ExpectedVersion ([string] $job.ExpectedVersion)
    $payload = [ordered]@{
        Succeeded = $true
        ExtensionRoot = [string] $installation.ExtensionRoot
        Content = $installation.Content
        WasUpdate = [bool] $installation.WasUpdate
        PreviousVersion = [string] $installation.PreviousVersion
        InstalledVersion = [string] $installation.InstalledVersion
    }
}
catch {
    $category = [string] $_.Exception.Data['ExtGuideCategory']
    $recovery = [string] $_.Exception.Data['ExtGuideRecovery']
    if ([string]::IsNullOrWhiteSpace($category)) { $category = 'Destination' }
    if ([string]::IsNullOrWhiteSpace($recovery)) { $recovery = 'Run ExtGuide again from a regular Windows PowerShell window.' }
    $payload = [ordered]@{
        Succeeded = $false
        Category = $category
        Message = $_.Exception.Message
        Recovery = $recovery
    }
}

$json = $payload | ConvertTo-Json -Depth 8
[System.IO.File]::WriteAllText([string] $job.ResultPath, $json, (New-Object System.Text.UTF8Encoding($true)))
'@
    return $parts -join "`r`n`r`n"
}

function Start-ExtGuideUnvirtualizedProcess {
    param([Parameter(Mandatory = $true)][string] $CommandLine)

    try {
        $result = Invoke-CimMethod -ClassName Win32_Process -MethodName Create -Arguments @{ CommandLine = $CommandLine } -ErrorAction Stop
    }
    catch {
        Throw-ExtGuideError -Category 'Destination' -Message 'Windows could not start an unvirtualized extension installer.' -Recovery 'Run ExtGuide again from a regular Windows PowerShell window outside the packaged application.' -InnerException $_.Exception
    }
    if ([int] $result.ReturnValue -ne 0) {
        Throw-ExtGuideError -Category 'Destination' -Message "Windows could not start the extension installer (WMI return code $($result.ReturnValue))." -Recovery 'Run ExtGuide again from a regular Windows PowerShell window outside the packaged application.'
    }
    return [int] $result.ProcessId
}

function Start-ExtGuideElevatedProcess {
    param(
        [Parameter(Mandatory = $true)][string] $PowerShellPath,
        [Parameter(Mandatory = $true)][string] $EncodedCommand
    )

    try {
        $process = Start-Process -FilePath $PowerShellPath -ArgumentList @('-NoProfile', '-NonInteractive', '-WindowStyle', 'Hidden', '-ExecutionPolicy', 'Bypass', '-EncodedCommand', $EncodedCommand) -Verb RunAs -WindowStyle Hidden -PassThru -ErrorAction Stop
        return [int] $process.Id
    }
    catch {
        $exception = New-ExtGuideException -Category 'Destination' -Message 'Windows did not grant administrator permission for the selected installation location.' -Recovery 'Choose another folder, or try again and approve the Windows permission prompt.' -InnerException $_.Exception
        $exception.Data['ExtGuideElevationDeclined'] = $true
        throw $exception
    }
}

function Remove-ExtGuideInstallJobDirectory {
    param([Parameter(Mandatory = $true)][string] $JobDirectory)

    $fullJobDirectory = [System.IO.Path]::GetFullPath($JobDirectory)
    $tempRoot = [System.IO.Path]::GetFullPath([System.IO.Path]::GetTempPath()).TrimEnd('\') + '\'
    $leaf = Split-Path -Leaf $fullJobDirectory
    if ($fullJobDirectory.StartsWith($tempRoot, [System.StringComparison]::OrdinalIgnoreCase) -and $leaf -match '^ExtGuide-(install|settings)-[0-9a-f]{32}$') {
        Remove-Item -LiteralPath $fullJobDirectory -Recurse -Force -ErrorAction SilentlyContinue
    }
}

function Install-ExtGuideArchiveOutOfProcess {
    param(
        [Parameter(Mandatory = $true)][byte[]] $ArchiveBytes,
        [Parameter(Mandatory = $true)][string] $Destination,
        [Parameter(Mandatory = $true)][string] $ExtensionRoot,
        [Parameter(Mandatory = $true)] $InstallContext,
        [switch] $Elevated
    )

    $jobDirectory = Join-Path ([System.IO.Path]::GetTempPath()) ('ExtGuide-install-' + [guid]::NewGuid().ToString('N'))
    try {
        $null = New-Item -ItemType Directory -Path $jobDirectory -Force -ErrorAction Stop
        $workerPath = Join-Path $jobDirectory 'worker.ps1'
        $archivePath = Join-Path $jobDirectory 'extension.zip'
        $jobPath = Join-Path $jobDirectory 'job.json'
        $resultPath = Join-Path $jobDirectory 'result.json'

        [System.IO.File]::WriteAllText($workerPath, (Get-ExtGuideInstallWorkerSource), (New-Object System.Text.UTF8Encoding($true)))
        [System.IO.File]::WriteAllBytes($archivePath, $ArchiveBytes)
        [System.IO.File]::WriteAllText($resultPath, '')

        $physicalWorkerPath = Get-ExtGuideFinalPath -Path $workerPath
        $physicalArchivePath = Get-ExtGuideFinalPath -Path $archivePath
        $physicalResultPath = Get-ExtGuideFinalPath -Path $resultPath
        $job = [ordered]@{
            ArchivePath = $physicalArchivePath
            Destination = [System.IO.Path]::GetFullPath($Destination)
            ExtensionRoot = $ExtensionRoot
            ResultPath = $physicalResultPath
            IntegrationId = [string] $InstallContext.IntegrationId
            Publisher = [string] $InstallContext.Publisher
            InstallFolderName = [string] $InstallContext.InstallFolderName
            ArchiveSha256 = [string] $InstallContext.ArchiveSha256
            ExpectedVersion = [string] $InstallContext.ExpectedVersion
        }
        [System.IO.File]::WriteAllText($jobPath, ($job | ConvertTo-Json), (New-Object System.Text.UTF8Encoding($true)))
        $physicalJobPath = Get-ExtGuideFinalPath -Path $jobPath

        $workerCommand = "& '$($physicalWorkerPath.Replace("'", "''"))' -JobPath '$($physicalJobPath.Replace("'", "''"))'"
        $encodedCommand = [Convert]::ToBase64String([System.Text.Encoding]::Unicode.GetBytes($workerCommand))
        $powerShell = Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe'
        if ($Elevated) {
            $null = Start-ExtGuideElevatedProcess -PowerShellPath $powerShell -EncodedCommand $encodedCommand
        }
        else {
            $commandLine = '"{0}" -NoProfile -NonInteractive -WindowStyle Hidden -ExecutionPolicy Bypass -EncodedCommand {1}' -f $powerShell, $encodedCommand
            $null = Start-ExtGuideUnvirtualizedProcess -CommandLine $commandLine
        }

        $deadline = [DateTime]::UtcNow.AddMinutes(5)
        while ([DateTime]::UtcNow -lt $deadline) {
            if ((Get-Item -LiteralPath $resultPath -ErrorAction SilentlyContinue).Length -gt 0) { break }
            Start-Sleep -Milliseconds 100
        }
        if ((Get-Item -LiteralPath $resultPath -ErrorAction SilentlyContinue).Length -le 0) {
            Throw-ExtGuideError -Category 'Destination' -Message 'The unvirtualized extension installer did not finish in time.' -Recovery 'Run ExtGuide again from a regular Windows PowerShell window outside the packaged application.'
        }

        $result = Get-Content -LiteralPath $resultPath -Raw | ConvertFrom-Json -ErrorAction Stop
        if (-not [bool] $result.Succeeded) {
            Throw-ExtGuideError -Category ([string] $result.Category) -Message ([string] $result.Message) -Recovery ([string] $result.Recovery)
        }
        $content = @{}
        if ($null -ne $result.Content) {
            foreach ($property in $result.Content.PSObject.Properties) { $content[$property.Name] = $property.Value }
        }
        return [pscustomobject]@{
            ExtensionRoot = [string] $result.ExtensionRoot
            Content = $content
            WasUpdate = [bool] $result.WasUpdate
            PreviousVersion = [string] $result.PreviousVersion
            InstalledVersion = [string] $result.InstalledVersion
        }
    }
    finally {
        Remove-ExtGuideInstallJobDirectory -JobDirectory $jobDirectory
    }
}

function Install-ExtGuideArchiveForWindows {
    param(
        [Parameter(Mandatory = $true)][byte[]] $ArchiveBytes,
        [Parameter(Mandatory = $true)][string] $Destination,
        [Parameter(Mandatory = $true)][string] $ExtensionRoot,
        $InstallContext,
        [scriptblock] $VirtualizationDetector,
        [scriptblock] $OutOfProcessInstaller,
        [scriptblock] $InProcessInstaller,
        [scriptblock] $ElevatedInstaller
    )

    if ($null -eq $InstallContext) {
        $InstallContext = [pscustomobject]@{ UseElevation = $false; IntegrationId = ''; Publisher = ''; InstallFolderName = ''; ArchiveSha256 = (Get-ExtGuideSha256 -Bytes $ArchiveBytes); ExpectedVersion = '' }
    }
    if ($null -eq $VirtualizationDetector) { $VirtualizationDetector = { param($Path) Test-ExtGuidePathVirtualized -Destination $Path } }
    if ($null -eq $OutOfProcessInstaller) { $OutOfProcessInstaller = { param($Bytes, $Target, $Root, $Context) Install-ExtGuideArchiveOutOfProcess -ArchiveBytes $Bytes -Destination $Target -ExtensionRoot $Root -InstallContext $Context } }
    if ($null -eq $ElevatedInstaller) { $ElevatedInstaller = { param($Bytes, $Target, $Root, $Context) Install-ExtGuideArchiveOutOfProcess -ArchiveBytes $Bytes -Destination $Target -ExtensionRoot $Root -InstallContext $Context -Elevated } }
    if ($null -eq $InProcessInstaller) {
        $InProcessInstaller = {
            param($Bytes, $Target, $Root, $Context)
            Install-ExtGuideArchive -ArchiveBytes $Bytes -Destination $Target -ExtensionRoot $Root -IntegrationId ([string] $Context.IntegrationId) -Publisher ([string] $Context.Publisher) -InstallFolderName ([string] $Context.InstallFolderName) -ArchiveSha256 ([string] $Context.ArchiveSha256) -ExpectedVersion ([string] $Context.ExpectedVersion)
        }
    }

    if ([bool] $InstallContext.UseElevation) {
        return & $ElevatedInstaller $ArchiveBytes $Destination $ExtensionRoot $InstallContext
    }

    if (& $VirtualizationDetector $Destination) {
        return & $OutOfProcessInstaller $ArchiveBytes $Destination $ExtensionRoot $InstallContext
    }
    return & $InProcessInstaller $ArchiveBytes $Destination $ExtensionRoot $InstallContext
}


function Get-ExtGuideSettingsPath {
    return Join-Path (Join-Path ([Environment]::GetFolderPath('LocalApplicationData')) 'ExtGuide') 'settings.json'
}

function Get-ExtGuideSettingsWorkerSource {
    return @'
[CmdletBinding()]
param([Parameter(Mandatory = $true)][string] $JobPath)

$ErrorActionPreference = 'Stop'
Set-StrictMode -Version 2.0
$job = Get-Content -LiteralPath $JobPath -Raw | ConvertFrom-Json -ErrorAction Stop
try {
    if ([string] $job.Operation -eq 'Read') {
        $exists = Test-Path -LiteralPath ([string] $job.SettingsPath) -PathType Leaf
        $settingsJson = if ($exists) { [System.IO.File]::ReadAllText([string] $job.SettingsPath) } else { '' }
        $payload = [ordered]@{ Succeeded = $true; Exists = $exists; SettingsJson = $settingsJson }
    }
    elseif ([string] $job.Operation -eq 'Write') {
        $settingsPath = [System.IO.Path]::GetFullPath([string] $job.SettingsPath)
        $directory = Split-Path -Parent $settingsPath
        $null = New-Item -ItemType Directory -Path $directory -Force -ErrorAction Stop
        $temporary = $settingsPath + '.tmp-' + [guid]::NewGuid().ToString('N')
        try {
            [System.IO.File]::WriteAllText($temporary, [string] $job.SettingsJson, (New-Object System.Text.UTF8Encoding($true)))
            Move-Item -LiteralPath $temporary -Destination $settingsPath -Force -ErrorAction Stop
        }
        finally {
            if (Test-Path -LiteralPath $temporary -PathType Leaf) { Remove-Item -LiteralPath $temporary -Force -ErrorAction SilentlyContinue }
        }
        $payload = [ordered]@{ Succeeded = $true; Exists = $true; SettingsJson = '' }
    }
    else {
        throw "Unsupported settings operation '$($job.Operation)'."
    }
}
catch {
    $payload = [ordered]@{ Succeeded = $false; Message = $_.Exception.Message }
}

[System.IO.File]::WriteAllText([string] $job.ResultPath, ($payload | ConvertTo-Json -Depth 5), (New-Object System.Text.UTF8Encoding($true)))
'@
}

function Invoke-ExtGuideSettingsIoOutOfProcess {
    param(
        [Parameter(Mandatory = $true)][ValidateSet('Read', 'Write')][string] $Operation,
        [Parameter(Mandatory = $true)][string] $SettingsPath,
        [string] $SettingsJson = ''
    )

    $jobDirectory = Join-Path ([System.IO.Path]::GetTempPath()) ('ExtGuide-settings-' + [guid]::NewGuid().ToString('N'))
    try {
        $null = New-Item -ItemType Directory -Path $jobDirectory -Force -ErrorAction Stop
        $workerPath = Join-Path $jobDirectory 'worker.ps1'
        $jobPath = Join-Path $jobDirectory 'job.json'
        $resultPath = Join-Path $jobDirectory 'result.json'
        [System.IO.File]::WriteAllText($workerPath, (Get-ExtGuideSettingsWorkerSource), (New-Object System.Text.UTF8Encoding($true)))
        [System.IO.File]::WriteAllText($resultPath, '')

        $physicalWorkerPath = Get-ExtGuideFinalPath -Path $workerPath
        $physicalResultPath = Get-ExtGuideFinalPath -Path $resultPath
        $job = [ordered]@{
            Operation = $Operation
            SettingsPath = [System.IO.Path]::GetFullPath($SettingsPath)
            SettingsJson = $SettingsJson
            ResultPath = $physicalResultPath
        }
        [System.IO.File]::WriteAllText($jobPath, ($job | ConvertTo-Json -Depth 5), (New-Object System.Text.UTF8Encoding($true)))
        $physicalJobPath = Get-ExtGuideFinalPath -Path $jobPath
        $workerCommand = "& '$($physicalWorkerPath.Replace("'", "''"))' -JobPath '$($physicalJobPath.Replace("'", "''"))'"
        $encodedCommand = [Convert]::ToBase64String([System.Text.Encoding]::Unicode.GetBytes($workerCommand))
        $powerShell = Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe'
        $commandLine = '"{0}" -NoProfile -NonInteractive -WindowStyle Hidden -ExecutionPolicy Bypass -EncodedCommand {1}' -f $powerShell, $encodedCommand
        $null = Start-ExtGuideUnvirtualizedProcess -CommandLine $commandLine

        $deadline = [DateTime]::UtcNow.AddMinutes(1)
        while ([DateTime]::UtcNow -lt $deadline) {
            if ((Get-Item -LiteralPath $resultPath -ErrorAction SilentlyContinue).Length -gt 0) { break }
            Start-Sleep -Milliseconds 100
        }
        if ((Get-Item -LiteralPath $resultPath -ErrorAction SilentlyContinue).Length -le 0) {
            Throw-ExtGuideError -Category 'Destination' -Message 'The unvirtualized settings operation did not finish in time.' -Recovery 'Run ExtGuide again from a regular Windows PowerShell window.'
        }
        $result = Get-Content -LiteralPath $resultPath -Raw | ConvertFrom-Json -ErrorAction Stop
        if (-not [bool] $result.Succeeded) {
            Throw-ExtGuideError -Category 'Destination' -Message 'ExtGuide could not access its real per-user settings file.' -Recovery 'Run ExtGuide again from a regular Windows PowerShell window.'
        }
        return $result
    }
    finally {
        Remove-ExtGuideInstallJobDirectory -JobDirectory $jobDirectory
    }
}

function Test-ExtGuideSettingsPathVirtualized {
    param([Parameter(Mandatory = $true)][string] $Path)
    try { return Test-ExtGuidePathVirtualized -Destination $Path }
    catch { return $false }
}

function Read-ExtGuideSettings {
    $path = Get-ExtGuideSettingsPath
    try {
        $json = $null
        if (Test-ExtGuideSettingsPathVirtualized -Path $path) {
            $result = Invoke-ExtGuideSettingsIoOutOfProcess -Operation 'Read' -SettingsPath $path
            if ([bool] $result.Exists) {
                $json = [string] $result.SettingsJson
            }
            elseif (Test-Path -LiteralPath $path -PathType Leaf) {
                $json = Get-Content -LiteralPath $path -Raw
                $null = Invoke-ExtGuideSettingsIoOutOfProcess -Operation 'Write' -SettingsPath $path -SettingsJson $json
            }
        }
        elseif (Test-Path -LiteralPath $path -PathType Leaf) {
            $json = Get-Content -LiteralPath $path -Raw
        }
        if ([string]::IsNullOrWhiteSpace($json)) { return @{ destinations = @{}; chromePath = $null } }
        $raw = $json | ConvertFrom-Json -ErrorAction Stop
        $destinations = @{}
        if ($null -ne $raw.destinations) {
            foreach ($property in $raw.destinations.PSObject.Properties) { $destinations[$property.Name] = [string] $property.Value }
        }
        return @{ destinations = $destinations; chromePath = [string] $raw.chromePath }
    }
    catch { return @{ destinations = @{}; chromePath = $null } }
}

function Write-ExtGuideSettings {
    param([Parameter(Mandatory = $true)][hashtable] $Settings)

    $path = Get-ExtGuideSettingsPath
    $json = $Settings | ConvertTo-Json -Depth 5
    if (Test-ExtGuideSettingsPathVirtualized -Path $path) {
        $null = Invoke-ExtGuideSettingsIoOutOfProcess -Operation 'Write' -SettingsPath $path -SettingsJson $json
        return
    }
    $directory = Split-Path -Parent $path
    $null = New-Item -ItemType Directory -Path $directory -Force
    $temporary = $path + '.tmp-' + [guid]::NewGuid().ToString('N')
    try {
        $json | Set-Content -LiteralPath $temporary -Encoding UTF8
        Move-Item -LiteralPath $temporary -Destination $path -Force
    }
    finally { if (Test-Path -LiteralPath $temporary) { Remove-Item -LiteralPath $temporary -Force -ErrorAction SilentlyContinue } }
}

function Get-ExtGuideSettingsKey { param($Manifest) return ([string] $Manifest.publisher + '|' + [string] $Manifest.installFolderName) }
function Get-ExtGuideRememberedDestination { param($Manifest) $settings = Read-ExtGuideSettings; return [string] $settings.destinations[(Get-ExtGuideSettingsKey -Manifest $Manifest)] }
function Set-ExtGuideRememberedDestination { param($Manifest, [string] $Destination) $settings = Read-ExtGuideSettings; $settings.destinations[(Get-ExtGuideSettingsKey -Manifest $Manifest)] = $Destination; Write-ExtGuideSettings -Settings $settings }
function Get-ExtGuideRememberedChrome { return [string] (Read-ExtGuideSettings).chromePath }
function Set-ExtGuideRememberedChrome { param([string] $Path) $settings = Read-ExtGuideSettings; $settings.chromePath = $Path; Write-ExtGuideSettings -Settings $settings }


function ConvertFrom-ExtGuideCommandPath {
    param([string] $Command)

    if ([string]::IsNullOrWhiteSpace($Command)) { return $null }
    $quoted = [regex]::Match($Command, '^\s*"([^"]+\.exe)"')
    if ($quoted.Success) { return $quoted.Groups[1].Value }
    $plain = [regex]::Match($Command, '^\s*([^\s]+\.exe)')
    if ($plain.Success) { return $plain.Groups[1].Value }
    return $null
}

function Get-ExtGuideRunningChromeCandidates {
    $paths = @()
    Get-Process -Name chrome -ErrorAction SilentlyContinue | ForEach-Object {
        try {
            $path = $_.Path
            if ([string]::IsNullOrWhiteSpace($path)) { $path = $_.MainModule.FileName }
            if (-not [string]::IsNullOrWhiteSpace($path)) { $paths += $path }
        }
        catch { }
    }
    return $paths
}

function Get-ExtGuideRegistryValue {
    param(
        [Microsoft.Win32.RegistryHive] $Hive,
        [Microsoft.Win32.RegistryView] $View,
        [string] $SubKey,
        [string] $ValueName
    )

    $baseKey = $null
    $key = $null
    try {
        $baseKey = [Microsoft.Win32.RegistryKey]::OpenBaseKey($Hive, $View)
        $key = $baseKey.OpenSubKey($SubKey)
        if ($null -eq $key) { return $null }
        return $key.GetValue($ValueName, $null, [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
    }
    catch { return $null }
    finally {
        if ($null -ne $key) { $key.Dispose() }
        if ($null -ne $baseKey) { $baseKey.Dispose() }
    }
}

function Get-ExtGuideRegisteredChromeCandidates {
    $candidates = @()
    $hives = @([Microsoft.Win32.RegistryHive]::CurrentUser, [Microsoft.Win32.RegistryHive]::LocalMachine)
    $views = @([Microsoft.Win32.RegistryView]::Registry64, [Microsoft.Win32.RegistryView]::Registry32)

    foreach ($hive in $hives) {
        foreach ($view in $views) {
            $appPath = Get-ExtGuideRegistryValue -Hive $hive -View $view -SubKey 'Software\Microsoft\Windows\CurrentVersion\App Paths\chrome.exe' -ValueName ''
            if ($appPath) { $candidates += [Environment]::ExpandEnvironmentVariables([string] $appPath) }

            $clientRoot = 'Software\Clients\StartMenuInternet'
            $baseKey = $null
            $root = $null
            try {
                $baseKey = [Microsoft.Win32.RegistryKey]::OpenBaseKey($hive, $view)
                $root = $baseKey.OpenSubKey($clientRoot)
                if ($null -ne $root) {
                    foreach ($clientName in $root.GetSubKeyNames()) {
                        if ($clientName -notmatch 'Chrome') { continue }
                        $command = Get-ExtGuideRegistryValue -Hive $hive -View $view -SubKey "$clientRoot\$clientName\shell\open\command" -ValueName ''
                        $path = ConvertFrom-ExtGuideCommandPath -Command ([string] $command)
                        if ($path) { $candidates += [Environment]::ExpandEnvironmentVariables($path) }
                    }
                }
            }
            catch { }
            finally {
                if ($null -ne $root) { $root.Dispose() }
                if ($null -ne $baseKey) { $baseKey.Dispose() }
            }

            $updateLocation = Get-ExtGuideRegistryValue -Hive $hive -View $view -SubKey 'Software\Google\Update\Clients\{8A69D345-D564-463c-AFF1-A69D9E530F96}' -ValueName 'location'
            if ($updateLocation) { $candidates += (Join-Path ([Environment]::ExpandEnvironmentVariables([string] $updateLocation)) 'chrome.exe') }

            $uninstallRoot = 'Software\Microsoft\Windows\CurrentVersion\Uninstall'
            $baseKey = $null
            $root = $null
            try {
                $baseKey = [Microsoft.Win32.RegistryKey]::OpenBaseKey($hive, $view)
                $root = $baseKey.OpenSubKey($uninstallRoot)
                if ($null -ne $root) {
                    foreach ($name in $root.GetSubKeyNames()) {
                        $subKey = $root.OpenSubKey($name)
                        try {
                            if ([string] $subKey.GetValue('DisplayName') -notmatch '^Google Chrome') { continue }
                            $location = [string] $subKey.GetValue('InstallLocation')
                            if ($location) { $candidates += (Join-Path ([Environment]::ExpandEnvironmentVariables($location)) 'chrome.exe') }
                            $iconPath = ConvertFrom-ExtGuideCommandPath -Command ([string] $subKey.GetValue('DisplayIcon'))
                            if ($iconPath) { $candidates += [Environment]::ExpandEnvironmentVariables($iconPath) }
                        }
                        finally { if ($null -ne $subKey) { $subKey.Dispose() } }
                    }
                }
            }
            catch { }
            finally {
                if ($null -ne $root) { $root.Dispose() }
                if ($null -ne $baseKey) { $baseKey.Dispose() }
            }
        }
    }

    foreach ($base in @($env:LOCALAPPDATA, $env:PROGRAMFILES, ${env:PROGRAMFILES(X86)})) {
        if ([string]::IsNullOrWhiteSpace($base)) { continue }
        $candidates += (Join-Path $base 'Google\Chrome\Application\chrome.exe')
    }
    return $candidates
}

function Test-ExtGuideChromeExecutable {
    param([Parameter(Mandatory = $true)][string] $Path)

    try {
        $normalized = [System.IO.Path]::GetFullPath([Environment]::ExpandEnvironmentVariables($Path.Trim('"')))
        if (-not (Test-Path -LiteralPath $normalized -PathType Leaf)) { return $false }
        $versionInfo = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($normalized)
        if ($versionInfo.ProductName -notmatch '^Google Chrome') { return $false }
        $signature = Get-AuthenticodeSignature -LiteralPath $normalized -ErrorAction Stop
        if ($signature.Status -ne [System.Management.Automation.SignatureStatus]::Valid -or $null -eq $signature.SignerCertificate) { return $false }
        return $signature.SignerCertificate.Subject -match 'O=Google (LLC|Inc)'
    }
    catch { return $false }
}

function Initialize-ExtGuideForegroundInterop {
    if ('ExtGuide.Native.ForegroundWindow' -as [type]) { return }
    Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;

namespace ExtGuide.Native {
    public static class ForegroundWindow {
        [DllImport("user32.dll")]
        public static extern bool SetForegroundWindow(IntPtr hWnd);

        [DllImport("user32.dll")]
        public static extern IntPtr GetForegroundWindow();

        [DllImport("user32.dll")]
        public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);

        [DllImport("user32.dll")]
        public static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint processId);
    }
}
'@ -ErrorAction Stop
}

function Get-ExtGuideWindowExecutable {
    param([Parameter(Mandatory = $true)][IntPtr] $Handle)

    Initialize-ExtGuideForegroundInterop
    [uint32] $processId = 0
    $null = [ExtGuide.Native.ForegroundWindow]::GetWindowThreadProcessId($Handle, [ref] $processId)
    if ($processId -eq 0) { return $null }
    try { return (Get-Process -Id $processId -ErrorAction Stop).Path }
    catch { return $null }
}

function Find-ExtGuideChromeWindow {
    param(
        [Parameter(Mandatory = $true)][string] $Executable,
        [int] $TimeoutMilliseconds = 3000
    )

    Initialize-ExtGuideForegroundInterop
    $expected = [System.IO.Path]::GetFullPath($Executable)
    $deadline = [DateTime]::UtcNow.AddMilliseconds($TimeoutMilliseconds)
    do {
        $foreground = [ExtGuide.Native.ForegroundWindow]::GetForegroundWindow()
        if ($foreground -ne [IntPtr]::Zero) {
            $foregroundExecutable = Get-ExtGuideWindowExecutable -Handle $foreground
            if (-not [string]::IsNullOrWhiteSpace($foregroundExecutable) -and
                [string]::Equals([System.IO.Path]::GetFullPath($foregroundExecutable), $expected, [System.StringComparison]::OrdinalIgnoreCase)) {
                return [pscustomobject]@{ Handle = $foreground; Executable = $foregroundExecutable }
            }
        }

        $candidates = @(Get-Process -Name chrome -ErrorAction SilentlyContinue | Where-Object { $_.MainWindowHandle -ne 0 } | Sort-Object StartTime -Descending)
        foreach ($candidate in $candidates) {
            try { $candidateExecutable = $candidate.Path }
            catch { continue }
            if (-not [string]::IsNullOrWhiteSpace($candidateExecutable) -and
                [string]::Equals([System.IO.Path]::GetFullPath($candidateExecutable), $expected, [System.StringComparison]::OrdinalIgnoreCase)) {
                return [pscustomobject]@{ Handle = [IntPtr] $candidate.MainWindowHandle; Executable = $candidateExecutable }
            }
        }
        Start-Sleep -Milliseconds 100
    } while ([DateTime]::UtcNow -lt $deadline)
    return $null
}

function Initialize-ExtGuideUiAutomation {
    if ('System.Windows.Automation.AutomationElement' -as [type]) { return }
    Add-Type -AssemblyName UIAutomationClient -ErrorAction Stop
    Add-Type -AssemblyName UIAutomationTypes -ErrorAction Stop
}

function Get-ExtGuideChromeAutomationRoot {
    param([Parameter(Mandatory = $true)][IntPtr] $Handle)

    Initialize-ExtGuideUiAutomation
    return [System.Windows.Automation.AutomationElement]::FromHandle($Handle)
}

function Find-ExtGuideChromeAddressBar {
    param([Parameter(Mandatory = $true)][IntPtr] $Handle)

    $root = Get-ExtGuideChromeAutomationRoot -Handle $Handle
    if ($null -eq $root) { return $null }
    $condition = New-Object System.Windows.Automation.PropertyCondition(
        [System.Windows.Automation.AutomationElement]::ClassNameProperty,
        'OmniboxViewViews'
    )
    return $root.FindFirst([System.Windows.Automation.TreeScope]::Descendants, $condition)
}

function Set-ExtGuideChromeAddressBarValue {
    param(
        [Parameter(Mandatory = $true)] $AddressBar,
        [Parameter(Mandatory = $true)][string] $Value
    )

    Initialize-ExtGuideUiAutomation
    $pattern = $null
    if (-not $AddressBar.TryGetCurrentPattern([System.Windows.Automation.ValuePattern]::Pattern, [ref] $pattern)) {
        throw 'The verified Chrome address bar does not support direct value injection.'
    }
    if ($pattern.Current.IsReadOnly) { throw 'The verified Chrome address bar is read-only.' }
    $AddressBar.SetFocus()
    $pattern.SetValue($Value)
    $actual = [string] $pattern.Current.Value
    if (-not [string]::Equals($actual.TrimEnd('/'), $Value.TrimEnd('/'), [System.StringComparison]::OrdinalIgnoreCase)) {
        throw 'Chrome did not retain the injected extensions page address.'
    }
}

function Find-ExtGuideChromeAddressSuggestion {
    param(
        [Parameter(Mandatory = $true)][IntPtr] $Handle,
        [Parameter(Mandatory = $true)][string] $Uri,
        [int] $TimeoutMilliseconds = 2000
    )

    Initialize-ExtGuideUiAutomation
    $target = $Uri.TrimEnd('/')
    $deadline = [DateTime]::UtcNow.AddMilliseconds($TimeoutMilliseconds)
    do {
        $root = Get-ExtGuideChromeAutomationRoot -Handle $Handle
        $condition = New-Object System.Windows.Automation.PropertyCondition(
            [System.Windows.Automation.AutomationElement]::ControlTypeProperty,
            [System.Windows.Automation.ControlType]::ListItem
        )
        $items = $root.FindAll([System.Windows.Automation.TreeScope]::Descendants, $condition)
        for ($index = 0; $index -lt $items.Count; $index++) {
            $candidate = $items.Item($index)
            $name = [string] $candidate.Current.Name
            if (-not $name.StartsWith($target, [System.StringComparison]::OrdinalIgnoreCase)) { continue }
            $remainder = $name.Substring($target.Length)
            if ($remainder.Length -gt 0 -and $remainder[0] -match '[A-Za-z0-9_-]') { continue }
            $pattern = $null
            if ($candidate.TryGetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern, [ref] $pattern)) { return $candidate }
        }
        Start-Sleep -Milliseconds 100
    } while ([DateTime]::UtcNow -lt $deadline)
    return $null
}

function Get-ExtGuideChromeSelectedTab {
    param([Parameter(Mandatory = $true)][IntPtr] $Handle)

    Initialize-ExtGuideUiAutomation
    $root = Get-ExtGuideChromeAutomationRoot -Handle $Handle
    $condition = New-Object System.Windows.Automation.PropertyCondition(
        [System.Windows.Automation.AutomationElement]::ControlTypeProperty,
        [System.Windows.Automation.ControlType]::TabItem
    )
    $tabs = $root.FindAll([System.Windows.Automation.TreeScope]::Descendants, $condition)
    for ($index = 0; $index -lt $tabs.Count; $index++) {
        $tab = $tabs.Item($index)
        $pattern = $null
        if ($tab.TryGetCurrentPattern([System.Windows.Automation.SelectionItemPattern]::Pattern, [ref] $pattern) -and $pattern.Current.IsSelected) {
            return $tab
        }
    }
    return $null
}

function Test-ExtGuideAutomationElementSelected {
    param([Parameter(Mandatory = $true)] $Element)

    try {
        $pattern = $null
        return $Element.TryGetCurrentPattern([System.Windows.Automation.SelectionItemPattern]::Pattern, [ref] $pattern) -and $pattern.Current.IsSelected
    }
    catch { return $false }
}

function Invoke-ExtGuideAutomationElement {
    param([Parameter(Mandatory = $true)] $Element)

    Initialize-ExtGuideUiAutomation
    $pattern = $null
    if (-not $Element.TryGetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern, [ref] $pattern)) {
        throw 'The Chrome automation element does not support its native invoke action.'
    }
    $pattern.Invoke()
}

function Close-ExtGuideChromeTab {
    param([Parameter(Mandatory = $true)] $Tab)

    Initialize-ExtGuideUiAutomation
    try {
        $condition = New-Object System.Windows.Automation.PropertyCondition(
            [System.Windows.Automation.AutomationElement]::ClassNameProperty,
            'TabCloseButton'
        )
        $closeButton = $Tab.FindFirst([System.Windows.Automation.TreeScope]::Descendants, $condition)
        if ($null -ne $closeButton) { Invoke-ExtGuideAutomationElement -Element $closeButton }
    }
    catch { }
}

function New-ExtGuideChromeNavigationOperations {
    return @{
        StartChrome = { param($Executable, $Uri) Start-Process -FilePath $Executable -ArgumentList $Uri -PassThru }
        FindChromeWindow = { param($Executable) Find-ExtGuideChromeWindow -Executable $Executable }
        RestoreWindow = { param($Handle) Initialize-ExtGuideForegroundInterop; [ExtGuide.Native.ForegroundWindow]::ShowWindow($Handle, 9) }
        ActivateWindow = { param($Handle) Initialize-ExtGuideForegroundInterop; [ExtGuide.Native.ForegroundWindow]::SetForegroundWindow($Handle) }
        GetForegroundWindow = { Initialize-ExtGuideForegroundInterop; [ExtGuide.Native.ForegroundWindow]::GetForegroundWindow() }
        GetWindowExecutable = { param($Handle) Get-ExtGuideWindowExecutable -Handle $Handle }
        GetSelectedTab = { param($Handle) Get-ExtGuideChromeSelectedTab -Handle $Handle }
        FindAddressBar = { param($Handle) Find-ExtGuideChromeAddressBar -Handle $Handle }
        SetAddressBarValue = { param($AddressBar, $Value) Set-ExtGuideChromeAddressBarValue -AddressBar $AddressBar -Value $Value }
        FindAddressSuggestion = { param($Handle, $Uri) Find-ExtGuideChromeAddressSuggestion -Handle $Handle -Uri $Uri }
        InvokeElement = { param($Element) Invoke-ExtGuideAutomationElement -Element $Element }
        IsElementSelected = { param($Element) Test-ExtGuideAutomationElementSelected -Element $Element }
        CloseElement = { param($Element) Close-ExtGuideChromeTab -Tab $Element }
        Delay = { param($Milliseconds) Start-Sleep -Milliseconds $Milliseconds }
    }
}

function Open-ExtGuideChromeExtensionsPage {
    param(
        [Parameter(Mandatory = $true)][string] $Executable,
        [string] $Uri = 'chrome://extensions/',
        [hashtable] $Operations = (New-ExtGuideChromeNavigationOperations)
    )

    $requiredOperations = @('StartChrome', 'FindChromeWindow', 'RestoreWindow', 'ActivateWindow', 'GetForegroundWindow', 'GetWindowExecutable', 'GetSelectedTab', 'FindAddressBar', 'SetAddressBarValue', 'FindAddressSuggestion', 'InvokeElement', 'IsElementSelected', 'CloseElement', 'Delay')
    foreach ($name in $requiredOperations) {
        if (-not $Operations.ContainsKey($name) -or $Operations[$name] -isnot [scriptblock]) {
            throw "Chrome navigation operation '$name' is unavailable."
        }
    }

    $null = & $Operations.StartChrome $Executable 'about:blank'
    $null = & $Operations.Delay 900
    $window = & $Operations.FindChromeWindow $Executable
    if ($null -eq $window -or [IntPtr] $window.Handle -eq [IntPtr]::Zero) {
        throw 'ExtGuide could not find a Chrome window after starting Chrome.'
    }

    $handle = [IntPtr] $window.Handle
    $null = & $Operations.RestoreWindow $handle
    if (-not (& $Operations.ActivateWindow $handle)) {
        throw 'ExtGuide could not activate the verified Chrome window.'
    }
    $null = & $Operations.Delay 200

    $foreground = [IntPtr] (& $Operations.GetForegroundWindow)
    $foregroundExecutable = & $Operations.GetWindowExecutable $foreground
    if ($foreground -ne $handle -or [string]::IsNullOrWhiteSpace([string] $foregroundExecutable) -or
        -not [string]::Equals([System.IO.Path]::GetFullPath([string] $foregroundExecutable), [System.IO.Path]::GetFullPath($Executable), [System.StringComparison]::OrdinalIgnoreCase)) {
        throw 'ExtGuide did not inject the address because the foreground window was not the verified Chrome executable.'
    }

    $createdTab = & $Operations.GetSelectedTab $handle
    $addressBar = & $Operations.FindAddressBar $handle
    if ($null -eq $addressBar) { throw 'ExtGuide could not locate the verified Chrome address bar.' }
    $null = & $Operations.SetAddressBarValue $addressBar $Uri
    $null = & $Operations.Delay 300
    $suggestion = & $Operations.FindAddressSuggestion $handle $Uri
    if ($null -eq $suggestion) { throw 'ExtGuide could not locate Chrome navigation for the injected extensions page address.' }
    $null = & $Operations.InvokeElement $suggestion
    $null = & $Operations.Delay 300
    if ($null -ne $createdTab -and -not (& $Operations.IsElementSelected $createdTab)) {
        $null = & $Operations.CloseElement $createdTab
    }
    return [pscustomobject]@{
        Executable = $Executable
        Uri = $Uri
        NavigationMethod = 'UiAutomationValueAndInvoke'
        KeyboardSimulation = $false
    }
}

function Get-ExtGuideManagedPolicyNotice {
    $messages = @()
    foreach ($hive in @([Microsoft.Win32.RegistryHive]::CurrentUser, [Microsoft.Win32.RegistryHive]::LocalMachine)) {
        $developerTools = Get-ExtGuideRegistryValue -Hive $hive -View ([Microsoft.Win32.RegistryView]::Default) -SubKey 'Software\Policies\Google\Chrome' -ValueName 'DeveloperToolsAvailability'
        if ($null -ne $developerTools -and [int] $developerTools -eq 2) { $messages += Get-ExtGuideText -Key 'ManagedDeveloperTools' }
        $blockList = Get-ExtGuideRegistryValue -Hive $hive -View ([Microsoft.Win32.RegistryView]::Default) -SubKey 'Software\Policies\Google\Chrome\ExtensionInstallBlocklist' -ValueName '1'
        if ([string] $blockList -eq '*') { $messages += Get-ExtGuideText -Key 'ManagedExtensions' }
    }
    return ($messages | Select-Object -Unique) -join ' '
}


$script:ExtGuideCultureOverride = $null
$script:ExtGuideStringCache = @{}

function Set-ExtGuideCultureOverride {
    param([string] $CultureName)
    $script:ExtGuideCultureOverride = $CultureName
}

function Resolve-ExtGuideLanguage {
    param([string] $CultureName)

    if ([string]::IsNullOrWhiteSpace($CultureName)) { $CultureName = [System.Globalization.CultureInfo]::CurrentUICulture.Name }
    if ($CultureName -match '^zh-(TW|HK|MO|Hant)') { return 'zh-TW' }
    if ($CultureName -match '^zh-(CN|SG|Hans)') { return 'zh-TW' }
    if ($CultureName -match '^zh($|-)') { return 'zh-TW' }
    return 'en'
}

function Import-ExtGuideStrings {
    param([Parameter(Mandatory = $true)][string] $Language)

    if ($script:ExtGuideStringCache.ContainsKey($Language)) { return $script:ExtGuideStringCache[$Language] }
    $json = $null
    if ($null -ne $script:ExtGuideEmbeddedResources -and $script:ExtGuideEmbeddedResources.ContainsKey($Language)) {
        $json = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($script:ExtGuideEmbeddedResources[$Language]))
    }
    else {
        $resourcePath = Join-Path (Join-Path $script:ExtGuideModuleRoot 'Resources') ("strings.$Language.json")
        if (Test-Path -LiteralPath $resourcePath) { $json = Get-Content -LiteralPath $resourcePath -Raw -Encoding UTF8 }
    }
    if ([string]::IsNullOrWhiteSpace($json) -and $Language -ne 'en') { return Import-ExtGuideStrings -Language 'en' }
    $object = $json | ConvertFrom-Json
    $strings = @{}
    foreach ($property in $object.PSObject.Properties) { $strings[$property.Name] = [string] $property.Value }
    $script:ExtGuideStringCache[$Language] = $strings
    return $strings
}

function Get-ExtGuideText {
    param(
        [Parameter(Mandatory = $true)][string] $Key,
        [object[]] $Arguments = @(),
        [string] $CultureName
    )

    if ([string]::IsNullOrWhiteSpace($CultureName)) { $CultureName = $script:ExtGuideCultureOverride }
    $language = Resolve-ExtGuideLanguage -CultureName $CultureName
    $strings = Import-ExtGuideStrings -Language $language
    if (-not $strings.ContainsKey($Key)) { $strings = Import-ExtGuideStrings -Language 'en' }
    if (-not $strings.ContainsKey($Key)) { return $Key }
    if ($Arguments.Count -gt 0) { return [string]::Format($strings[$Key], $Arguments) }
    return $strings[$Key]
}


$script:ExtGuideUiSessions = @{}

function Initialize-ExtGuideWinForms {
    Add-Type -AssemblyName System.Windows.Forms -ErrorAction Stop
    Add-Type -AssemblyName System.Drawing -ErrorAction Stop
    [System.Windows.Forms.Application]::EnableVisualStyles()
}

function New-ExtGuideForm {
    param([string] $Title)

    Initialize-ExtGuideWinForms
    $form = New-Object System.Windows.Forms.Form
    $form.Text = $Title
    $form.ClientSize = New-Object System.Drawing.Size(620, 520)
    $form.StartPosition = 'CenterScreen'
    $form.FormBorderStyle = 'FixedDialog'
    $form.MaximizeBox = $false
    $form.MinimizeBox = $true
    $form.AutoScaleMode = 'Dpi'
    $form.Font = New-Object System.Drawing.Font('Segoe UI', 10)
    $form.BackColor = [System.Drawing.Color]::FromArgb(248, 249, 252)
    return $form
}

function New-ExtGuideLabel {
    param([string] $Text, [int] $X, [int] $Y, [int] $Width, [int] $Height, [float] $Size = 10, [bool] $Bold = $false)
    $label = New-Object System.Windows.Forms.Label
    $label.Text = $Text
    $label.Location = New-Object System.Drawing.Point($X, $Y)
    $label.Size = New-Object System.Drawing.Size($Width, $Height)
    $label.AutoEllipsis = $true
    $label.Font = New-Object System.Drawing.Font('Segoe UI', $Size, $(if ($Bold) { [System.Drawing.FontStyle]::Bold } else { [System.Drawing.FontStyle]::Regular }))
    return $label
}

function New-ExtGuideButton {
    param([string] $Text, [int] $X, [int] $Y, [int] $Width, [int] $TabIndex)
    $button = New-Object System.Windows.Forms.Button
    $button.Text = $Text
    $button.Location = New-Object System.Drawing.Point($X, $Y)
    $button.Size = New-Object System.Drawing.Size($Width, 38)
    $button.TabIndex = $TabIndex
    $button.AccessibleName = $Text
    return $button
}

function Show-ExtGuideAdministratorPermissionDialog {
    param([System.Windows.Forms.IWin32Window] $Owner)

    $form = New-ExtGuideForm -Title (Get-ExtGuideText -Key 'AdministratorPermissionTitle')
    $form.ClientSize = New-Object System.Drawing.Size(620, 260)
    $heading = New-ExtGuideLabel -Text (Get-ExtGuideText -Key 'AdministratorPermissionTitle') -X 28 -Y 24 -Width 560 -Height 38 -Size 16 -Bold $true
    $explanation = New-ExtGuideLabel -Text (Get-ExtGuideText -Key 'AdministratorPermissionExplanation') -X 30 -Y 72 -Width 550 -Height 82
    $elevate = New-ExtGuideButton -Text (Get-ExtGuideText -Key 'UseAdministratorPermission') -X 30 -Y 190 -Width 235 -TabIndex 0
    $change = New-ExtGuideButton -Text (Get-ExtGuideText -Key 'ChooseAnotherLocation') -X 277 -Y 190 -Width 185 -TabIndex 1
    $cancel = New-ExtGuideButton -Text (Get-ExtGuideText -Key 'Cancel') -X 474 -Y 190 -Width 110 -TabIndex 2
    $elevate.BackColor = [System.Drawing.Color]::FromArgb(36, 99, 235)
    $elevate.ForeColor = [System.Drawing.Color]::White
    $choice = @{ Value = 'Cancel' }
    $elevate.Add_Click({ $choice.Value = 'Elevate'; $form.DialogResult = [System.Windows.Forms.DialogResult]::OK })
    $change.Add_Click({ $choice.Value = 'Change'; $form.DialogResult = [System.Windows.Forms.DialogResult]::OK })
    $cancel.Add_Click({ $choice.Value = 'Cancel'; $form.DialogResult = [System.Windows.Forms.DialogResult]::Cancel })
    $form.AcceptButton = $elevate
    $form.CancelButton = $cancel
    $form.Controls.AddRange(@($heading, $explanation, $elevate, $change, $cancel))
    if ($null -ne $Owner) { $null = $form.ShowDialog($Owner) } else { $null = $form.ShowDialog() }
    $form.Dispose()
    return [string] $choice.Value
}

function Get-ExtGuideAssetImage {
    param([Parameter(Mandatory = $true)][string] $Name)

    $bytes = $null
    if ($null -ne $script:ExtGuideEmbeddedAssets -and $script:ExtGuideEmbeddedAssets.ContainsKey($Name)) {
        $bytes = [Convert]::FromBase64String($script:ExtGuideEmbeddedAssets[$Name])
    }
    else {
        $assetPath = Join-Path (Join-Path $script:ExtGuideModuleRoot 'Assets') $Name
        if (Test-Path -LiteralPath $assetPath -PathType Leaf) { $bytes = [System.IO.File]::ReadAllBytes($assetPath) }
    }
    if ($null -eq $bytes) { return $null }

    $stream = New-Object System.IO.MemoryStream(,$bytes)
    try {
        $source = [System.Drawing.Image]::FromStream($stream)
        try { return New-Object System.Drawing.Bitmap($source) }
        finally { $source.Dispose() }
    }
    finally { $stream.Dispose() }
}

function Get-ExtGuideVisualGuideAssetName {
    param([string] $CultureName)

    if ([string]::IsNullOrWhiteSpace($CultureName)) { $CultureName = $script:ExtGuideCultureOverride }
    if ((Resolve-ExtGuideLanguage -CultureName $CultureName) -eq 'zh-TW') { return 'chrome-extensions-page.zh-TW.png' }
    return 'chrome-extensions-page.png'
}

function Show-ExtGuideDestinationWindow {
    param($Manifest, [string] $RecommendedDestination, [string] $RememberedDestination)

    $form = New-ExtGuideForm -Title (Get-ExtGuideText -Key 'InstallTitle' -Arguments @([string] $Manifest.displayName))
    $initialDestination = if ($RememberedDestination) { $RememberedDestination } else { $RecommendedDestination }
    $state = @{ Destination = $initialDestination; IsCustom = [bool] $RememberedDestination; UseElevation = $false; IsUpdate = $false }
    $heading = New-ExtGuideLabel -Text (Get-ExtGuideText -Key 'InstallTitle' -Arguments @([string] $Manifest.displayName)) -X 28 -Y 24 -Width 560 -Height 40 -Size 18 -Bold $true
    $explanation = New-ExtGuideLabel -Text (Get-ExtGuideText -Key 'InstallExplanation') -X 30 -Y 76 -Width 550 -Height 52
    $pathLabel = New-ExtGuideLabel -Text (Get-ExtGuideText -Key 'FinalExtensionLocation') -X 30 -Y 145 -Width 300 -Height 25 -Bold $true
    $pathBox = New-Object System.Windows.Forms.TextBox
    $pathBox.Location = New-Object System.Drawing.Point(30, 176)
    $pathBox.Size = New-Object System.Drawing.Size(555, 28)
    $pathBox.ReadOnly = $true
    $pathBox.Text = $state.Destination
    $pathBox.TabIndex = 0
    $pathBox.AccessibleName = Get-ExtGuideText -Key 'FinalExtensionLocation'
    $changeButton = New-ExtGuideButton -Text (Get-ExtGuideText -Key 'ChangeLocation') -X 30 -Y 225 -Width 170 -TabIndex 1
    $installButton = New-ExtGuideButton -Text (Get-ExtGuideText -Key 'InstallExtension') -X 390 -Y 430 -Width 195 -TabIndex 2
    $cancelButton = New-ExtGuideButton -Text (Get-ExtGuideText -Key 'Cancel') -X 278 -Y 430 -Width 100 -TabIndex 3
    $installButton.BackColor = [System.Drawing.Color]::FromArgb(36, 99, 235)
    $installButton.ForeColor = [System.Drawing.Color]::White
    $cancelButton.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    $status = New-ExtGuideLabel -Text (Get-ExtGuideText -Key 'DestinationHint') -X 30 -Y 286 -Width 550 -Height 70

    $refreshOperation = {
        $candidateRoot = Join-Path $state.Destination ([string] $Manifest.extensionRoot)
        $state.IsUpdate = Test-Path -LiteralPath (Join-Path $candidateRoot 'manifest.json') -PathType Leaf
        if ($state.IsUpdate) {
            $form.Text = Get-ExtGuideText -Key 'UpdateTitle' -Arguments @([string] $Manifest.displayName)
            $heading.Text = Get-ExtGuideText -Key 'UpdateTitle' -Arguments @([string] $Manifest.displayName)
            $explanation.Text = Get-ExtGuideText -Key 'UpdateExplanation'
            $installButton.Text = Get-ExtGuideText -Key 'UpdateExtension'
            $installButton.AccessibleName = $installButton.Text
        }
        else {
            $form.Text = Get-ExtGuideText -Key 'InstallTitle' -Arguments @([string] $Manifest.displayName)
            $heading.Text = Get-ExtGuideText -Key 'InstallTitle' -Arguments @([string] $Manifest.displayName)
            $explanation.Text = Get-ExtGuideText -Key 'InstallExplanation'
            $installButton.Text = Get-ExtGuideText -Key 'InstallExtension'
            $installButton.AccessibleName = $installButton.Text
        }
    }
    $chooseFolder = {
        $chooser = New-Object System.Windows.Forms.FolderBrowserDialog
        $chooser.Description = Get-ExtGuideText -Key 'ChooseBaseFolder'
        if ($chooser.ShowDialog($form) -eq [System.Windows.Forms.DialogResult]::OK) {
            $state.Destination = Join-Path $chooser.SelectedPath ([string] $Manifest.installFolderName)
            $state.IsCustom = $true
            $pathBox.Text = $state.Destination
            & $refreshOperation
        }
        $chooser.Dispose()
    }
    $changeHandler = { & $chooseFolder }
    $installHandler = {
        if (Test-ExtGuideDestinationWritable -Destination $state.Destination) {
            $state.UseElevation = $false
            $form.DialogResult = [System.Windows.Forms.DialogResult]::OK
            return
        }
        $decision = Show-ExtGuideAdministratorPermissionDialog -Owner $form
        if ($decision -eq 'Elevate') {
            $state.UseElevation = $true
            $form.DialogResult = [System.Windows.Forms.DialogResult]::OK
        }
        elseif ($decision -eq 'Change') {
            & $chooseFolder
        }
        else {
            $form.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
        }
    }
    $changeButton.Add_Click($changeHandler)
    $installButton.Add_Click($installHandler)
    & $refreshOperation
    $form.AcceptButton = $installButton
    $form.CancelButton = $cancelButton
    $form.Controls.AddRange(@($heading, $explanation, $pathLabel, $pathBox, $changeButton, $cancelButton, $installButton, $status))
    $dialogResult = $form.ShowDialog()
    if ($dialogResult -ne [System.Windows.Forms.DialogResult]::OK) {
        $form.Dispose()
        return [pscustomobject]@{ Cancelled = $true; Destination = $null; IsCustom = $false }
    }
    $form.DialogResult = [System.Windows.Forms.DialogResult]::None
    $changeButton.Enabled = $false
    $cancelButton.Enabled = $false
    $installButton.Enabled = $false
    $status.Text = Get-ExtGuideText -Key 'Installing'
    $form.Show()
    [System.Windows.Forms.Application]::DoEvents()
    $sessionKey = [string] $Manifest.displayName
    $script:ExtGuideUiSessions[$sessionKey] = $form
    return [pscustomobject]@{ Cancelled = $false; Destination = $state.Destination; IsCustom = $state.IsCustom; UseElevation = $state.UseElevation; IsUpdate = $state.IsUpdate }
}

function Select-ExtGuideFallbackDestination {
    param($Manifest)

    Initialize-ExtGuideWinForms
    while ($true) {
        $chooser = New-Object System.Windows.Forms.FolderBrowserDialog
        $chooser.Description = Get-ExtGuideText -Key 'ChooseWritableBaseFolder'
        $dialogResult = $chooser.ShowDialog()
        $selectedPath = $chooser.SelectedPath
        $chooser.Dispose()
        if ($dialogResult -ne [System.Windows.Forms.DialogResult]::OK) { return $null }

        $destination = Join-Path $selectedPath ([string] $Manifest.installFolderName)
        if (Test-ExtGuideDestinationWritable -Destination $destination) {
            return [pscustomobject]@{ Destination = $destination; UseElevation = $false }
        }
        $decision = Show-ExtGuideAdministratorPermissionDialog
        if ($decision -eq 'Elevate') {
            return [pscustomobject]@{ Destination = $destination; UseElevation = $true }
        }
        if ($decision -eq 'Cancel') { return $null }
    }
}

function Close-ExtGuideUiSession {
    param([string] $DisplayName)

    if (-not $script:ExtGuideUiSessions.ContainsKey($DisplayName)) { return }
    $form = $script:ExtGuideUiSessions[$DisplayName]
    if ($null -ne $form -and -not $form.IsDisposed) { $form.Close(); $form.Dispose() }
    $script:ExtGuideUiSessions.Remove($DisplayName)
}

function Set-ExtGuideGuidanceControls {
    param([System.Windows.Forms.Form] $Form, [string] $DisplayName, [string] $InstalledRoot, [string] $ChromeExecutable, [string] $PolicyNotice, [bool] $WasUpdate = $false)

    $Form.SuspendLayout()
    foreach ($control in @($Form.Controls)) {
        if ($control -is [System.Windows.Forms.PictureBox] -and $null -ne $control.Image) {
            $control.Image.Dispose()
            $control.Image = $null
        }
    }
    $Form.Controls.Clear()
    $Form.ClientSize = if ($WasUpdate) { New-Object System.Drawing.Size(620, 520) } else { New-Object System.Drawing.Size(1160, 520) }
    $Form.Text = Get-ExtGuideText -Key $(if ($WasUpdate) { 'UpdateFinishTitle' } else { 'FinishTitle' }) -Arguments @($DisplayName)
    $Form.TopMost = $false
    $heading = New-ExtGuideLabel -Text (Get-ExtGuideText -Key $(if ($WasUpdate) { 'UpdateFinishHeading' } else { 'FinishHeading' })) -X 28 -Y 20 -Width $(if ($WasUpdate) { 560 } else { 1100 }) -Height 42 -Size 18 -Bold $true
    $subheading = New-ExtGuideLabel -Text (Get-ExtGuideText -Key $(if ($WasUpdate) { 'UpdateFinishSubheading' } else { 'FinishSubheading' })) -X 30 -Y 68 -Width $(if ($WasUpdate) { 550 } else { 1090 }) -Height 42
    $steps = if ($WasUpdate) {
        @((Get-ExtGuideText -Key 'UpdateStep1'), (Get-ExtGuideText -Key 'UpdateStep2'), (Get-ExtGuideText -Key 'UpdateStep3'))
    }
    else {
        @((Get-ExtGuideText -Key 'Step1'), (Get-ExtGuideText -Key 'Step2'), (Get-ExtGuideText -Key 'Step3'), (Get-ExtGuideText -Key 'Step4'), (Get-ExtGuideText -Key 'Step5'))
    }
    $y = 120
    foreach ($step in $steps) {
        $Form.Controls.Add((New-ExtGuideLabel -Text $step -X 42 -Y $y -Width 530 -Height 34 -Size 10.5))
        $y += 38
    }
    $guideImage = if ($WasUpdate) { $null } else { Get-ExtGuideAssetImage -Name (Get-ExtGuideVisualGuideAssetName) }
    $guidePicture = $null
    $guideCaption = $null
    if ($null -ne $guideImage) {
        $guidePicture = New-Object System.Windows.Forms.PictureBox
        $guidePicture.Location = New-Object System.Drawing.Point(650, 112)
        $guidePicture.Size = New-Object System.Drawing.Size(480, 347)
        $guidePicture.Image = $guideImage
        $guidePicture.SizeMode = [System.Windows.Forms.PictureBoxSizeMode]::Zoom
        $guidePicture.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
        $guidePicture.AccessibleName = Get-ExtGuideText -Key 'VisualGuideAccessibleName'
        $guideCaption = New-ExtGuideLabel -Text (Get-ExtGuideText -Key 'VisualGuideCaption') -X 650 -Y 465 -Width 480 -Height 48 -Size 8.5
    }
    $pathLabel = New-ExtGuideLabel -Text (Get-ExtGuideText -Key 'PreparedExtensionPath') -X 30 -Y 320 -Width 300 -Height 24 -Bold $true
    $pathBox = New-Object System.Windows.Forms.TextBox
    $pathBox.Location = New-Object System.Drawing.Point(30, 348)
    $pathBox.Size = New-Object System.Drawing.Size(555, 28)
    $pathBox.ReadOnly = $true
    $pathBox.Text = $InstalledRoot
    $pathBox.AccessibleName = Get-ExtGuideText -Key 'PreparedExtensionPath'
    $pathBox.TabIndex = 0
    $copy = New-ExtGuideButton -Text (Get-ExtGuideText -Key 'CopyPath') -X 30 -Y 394 -Width 120 -TabIndex 1
    $reopen = New-ExtGuideButton -Text (Get-ExtGuideText -Key 'ReopenExtensionsPage') -X 162 -Y 394 -Width 205 -TabIndex 2
    $openFolder = New-ExtGuideButton -Text (Get-ExtGuideText -Key 'OpenFolder') -X 379 -Y 394 -Width 130 -TabIndex 3
    $done = New-ExtGuideButton -Text (Get-ExtGuideText -Key 'Done') -X 520 -Y 394 -Width 65 -TabIndex 4
    $copyHandler = { [System.Windows.Forms.Clipboard]::SetText($InstalledRoot) }
    $reopenHandler = { if ($ChromeExecutable) { $null = Open-ExtGuideChromeExtensionsPage -Executable $ChromeExecutable } }
    $openFolderHandler = { if (Test-Path -LiteralPath $InstalledRoot) { Start-Process -FilePath 'explorer.exe' -ArgumentList $InstalledRoot } }
    $doneHandler = { $Form.Close() }
    $copy.Add_Click($copyHandler)
    $reopen.Add_Click($reopenHandler)
    $openFolder.Add_Click($openFolderHandler)
    $done.Add_Click($doneHandler)
    $Form.Controls.AddRange(@($heading, $subheading, $pathLabel, $pathBox, $copy, $reopen, $openFolder, $done))
    if ($null -ne $guidePicture) { $Form.Controls.AddRange(@($guidePicture, $guideCaption)) }
    if ($PolicyNotice) {
        $notice = New-ExtGuideLabel -Text $PolicyNotice -X 30 -Y 452 -Width $(if ($WasUpdate) { 550 } else { 1100 }) -Height 55 -Size 8.5
        $notice.ForeColor = [System.Drawing.Color]::FromArgb(146, 64, 14)
        $notice.AccessibleName = Get-ExtGuideText -Key 'ManagedPolicyNotice'
        $Form.Controls.Add($notice)
    }
    $Form.AcceptButton = $done
    $Form.ResumeLayout($true)
}

function Show-ExtGuideGuidanceWindow {
    param([string] $DisplayName, [string] $InstalledRoot, [string] $ChromeExecutable, [bool] $WasUpdate = $false)

    Initialize-ExtGuideWinForms
    $form = $script:ExtGuideUiSessions[$DisplayName]
    if ($null -eq $form -or $form.IsDisposed) { $form = New-ExtGuideForm -Title (Get-ExtGuideText -Key 'FinishTitle' -Arguments @($DisplayName)) }
    Set-ExtGuideGuidanceControls -Form $form -DisplayName $DisplayName -InstalledRoot $InstalledRoot -ChromeExecutable $ChromeExecutable -PolicyNotice (Get-ExtGuideManagedPolicyNotice) -WasUpdate $WasUpdate
    $form.TopMost = $true
    if (-not $form.Visible) { $form.Show() }
    $form.BringToFront()
    $null = $form.Activate()
    [System.Windows.Forms.Application]::DoEvents()
    $form.TopMost = $false
    while ($form.Visible) {
        [System.Windows.Forms.Application]::DoEvents()
        Start-Sleep -Milliseconds 40
    }
    $script:ExtGuideUiSessions.Remove($DisplayName)
    return [pscustomobject]@{ State = 'GuidanceReady'; DisplayName = $DisplayName; InstalledRoot = $InstalledRoot; WasUpdate = $WasUpdate }
}

function Select-ExtGuideChromeExecutable {
    param([string[]] $Candidates)

    Initialize-ExtGuideWinForms
    if ($Candidates.Count -gt 0) {
        $form = New-ExtGuideForm -Title (Get-ExtGuideText -Key 'ChooseChromeTitle')
        $form.ClientSize = New-Object System.Drawing.Size(620, 310)
        $heading = New-ExtGuideLabel -Text (Get-ExtGuideText -Key 'ChooseChromeHeading') -X 28 -Y 22 -Width 560 -Height 38 -Size 16 -Bold $true
        $explanation = New-ExtGuideLabel -Text (Get-ExtGuideText -Key 'ValidatedChromeExplanation') -X 30 -Y 66 -Width 550 -Height 28
        $list = New-Object System.Windows.Forms.ListBox
        $list.Location = New-Object System.Drawing.Point(30, 104)
        $list.Size = New-Object System.Drawing.Size(555, 105)
        $list.TabIndex = 0
        $list.AccessibleName = Get-ExtGuideText -Key 'ValidatedChromeInstallations'
        foreach ($candidate in $Candidates) { $null = $list.Items.Add($candidate) }
        $list.SelectedIndex = 0
        $useButton = New-ExtGuideButton -Text (Get-ExtGuideText -Key 'UseSelectedChrome') -X 390 -Y 244 -Width 195 -TabIndex 1
        $useButton.DialogResult = [System.Windows.Forms.DialogResult]::OK
        $browseButton = New-ExtGuideButton -Text (Get-ExtGuideText -Key 'ChooseAnotherFile') -X 30 -Y 244 -Width 190 -TabIndex 2
        $cancelButton = New-ExtGuideButton -Text (Get-ExtGuideText -Key 'Cancel') -X 278 -Y 244 -Width 100 -TabIndex 3
        $cancelButton.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
        $selection = @{ Path = $null }
        $useHandler = { $selection.Path = [string] $list.SelectedItem }
        $browseHandler = {
            $fileDialog = New-Object System.Windows.Forms.OpenFileDialog
            $fileDialog.Title = Get-ExtGuideText -Key 'SelectChromeTitle'
            $fileDialog.Filter = Get-ExtGuideText -Key 'ChromeFileFilter'
            if ($fileDialog.ShowDialog($form) -eq [System.Windows.Forms.DialogResult]::OK) {
                $selection.Path = $fileDialog.FileName
                $form.DialogResult = [System.Windows.Forms.DialogResult]::OK
            }
            $fileDialog.Dispose()
        }
        $useButton.Add_Click($useHandler)
        $browseButton.Add_Click($browseHandler)
        $form.AcceptButton = $useButton
        $form.CancelButton = $cancelButton
        $form.Controls.AddRange(@($heading, $explanation, $list, $useButton, $browseButton, $cancelButton))
        $dialogResult = $form.ShowDialog()
        $form.Dispose()
        if ($dialogResult -eq [System.Windows.Forms.DialogResult]::OK) { return $selection.Path }
        return $null
    }

    $chooser = New-Object System.Windows.Forms.OpenFileDialog
    $chooser.Title = Get-ExtGuideText -Key 'SelectChromeTitle'
    $chooser.Filter = Get-ExtGuideText -Key 'ChromeFileFilter'
    $chooser.CheckFileExists = $true
    $result = if ($chooser.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) { $chooser.FileName } else { $null }
    $chooser.Dispose()
    return $result
}

function Show-ExtGuideFailureWindow {
    param($Failure)
    Initialize-ExtGuideWinForms
    $text = "$($Failure.Message)`r`n`r`n$(Get-ExtGuideText -Key 'WhatToDo' -Arguments @($Failure.Recovery))"
    $null = [System.Windows.Forms.MessageBox]::Show($text, (Get-ExtGuideText -Key 'ErrorTitle' -Arguments @($Failure.Category)), 'OK', 'Error')
    foreach ($session in @($script:ExtGuideUiSessions.Values)) {
        if ($null -ne $session -and -not $session.IsDisposed) { $session.Close(); $session.Dispose() }
    }
    $script:ExtGuideUiSessions.Clear()
}

function Export-ExtGuideGuidancePreview {
    param([Parameter(Mandatory = $true)][string] $Path)

    Initialize-ExtGuideWinForms
    $previewName = Get-ExtGuideText -Key 'PreviewDisplayName'
    $form = New-ExtGuideForm -Title (Get-ExtGuideText -Key 'FinishTitle' -Arguments @($previewName))
    Set-ExtGuideGuidanceControls -Form $form -DisplayName $previewName -InstalledRoot 'C:\Users\Example\AppData\Local\ExtGuide\SampleExtension\extension' -ChromeExecutable '' -PolicyNotice ''
    $form.ShowInTaskbar = $false
    $form.Opacity = 0
    $form.Show()
    [System.Windows.Forms.Application]::DoEvents()
    $bitmap = New-Object System.Drawing.Bitmap($form.Width, $form.Height)
    $form.DrawToBitmap($bitmap, (New-Object System.Drawing.Rectangle(0, 0, $form.Width, $form.Height)))
    $bitmap.Save($Path, [System.Drawing.Imaging.ImageFormat]::Png)
    $bitmap.Dispose()
    $form.Close()
    $form.Dispose()
    return $Path
}


function Invoke-ExtGuideDownload {
    param([Parameter(Mandatory = $true)][uri] $Uri, [switch] $AsBytes)

    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
    $lastError = $null
    foreach ($attempt in 1..2) {
        $client = New-Object System.Net.WebClient
        try {
            $client.Headers['User-Agent'] = 'ExtGuide/0.1 (+https://github.com/)'
            if ($AsBytes) { return $client.DownloadData($Uri) }
            return $client.DownloadString($Uri)
        }
        catch {
            $lastError = $_.Exception
            if ($attempt -lt 2) { Start-Sleep -Milliseconds 250 }
        }
        finally { $client.Dispose() }
    }
    Throw-ExtGuideError -Category 'Network' -Message 'ExtGuide could not download a required release asset.' -Recovery 'Check the internet connection and ask the publisher to confirm that the release asset is available.' -InnerException $lastError
}

function Write-ExtGuideSafeLog {
    param([string] $Category)
    try {
        $directory = Join-Path (Join-Path ([Environment]::GetFolderPath('LocalApplicationData')) 'ExtGuide') 'logs'
        $null = New-Item -ItemType Directory -Path $directory -Force
        $line = ('{0:u} Category={1} Status=Failed' -f [DateTime]::UtcNow, $Category)
        Add-Content -LiteralPath (Join-Path $directory 'extguide.log') -Value $line -Encoding UTF8
    }
    catch { }
}

function New-ExtGuideWindowsHostAdapter {
    return @{
        FetchText = { param($Uri) Invoke-ExtGuideDownload -Uri $Uri }
        FetchBytes = { param($Uri) Invoke-ExtGuideDownload -Uri $Uri -AsBytes }
        GetLocalApplicationDataPath = { [Environment]::GetFolderPath('LocalApplicationData') }
        ChooseDestination = { param($Manifest, $Recommended, $Remembered) Show-ExtGuideDestinationWindow -Manifest $Manifest -RecommendedDestination $Recommended -RememberedDestination $Remembered }
        ChooseFallbackDestination = { param($Manifest) Select-ExtGuideFallbackDestination -Manifest $Manifest }
        CloseInstallSession = { param($DisplayName) Close-ExtGuideUiSession -DisplayName $DisplayName }
        DestinationExists = { param($Destination) Test-Path -LiteralPath $Destination -PathType Container }
        TestDestinationWritable = { param($Destination) Test-ExtGuideDestinationWritable -Destination $Destination }
        GetRememberedDestination = { param($Manifest) Get-ExtGuideRememberedDestination -Manifest $Manifest }
        RememberDestination = { param($Manifest, $Destination) Set-ExtGuideRememberedDestination -Manifest $Manifest -Destination $Destination }
        WriteExtension = { param($ArchiveBytes, $Destination, $ExtensionRoot, $InstallContext) Install-ExtGuideArchiveForWindows -ArchiveBytes $ArchiveBytes -Destination $Destination -ExtensionRoot $ExtensionRoot -InstallContext $InstallContext }
        GetRunningChromeCandidates = { Get-ExtGuideRunningChromeCandidates }
        GetRegisteredChromeCandidates = { Get-ExtGuideRegisteredChromeCandidates }
        GetRememberedChrome = { Get-ExtGuideRememberedChrome }
        TestChromeSignature = { param($Path) Test-ExtGuideChromeExecutable -Path $Path }
        ChooseChrome = { param($Candidates) Select-ExtGuideChromeExecutable -Candidates $Candidates }
        RememberChrome = { param($Path) Set-ExtGuideRememberedChrome -Path $Path }
        SetClipboard = { param($Text) Initialize-ExtGuideWinForms; [System.Windows.Forms.Clipboard]::SetText($Text) }
        LaunchChrome = { param($Executable, $Uri) Open-ExtGuideChromeExtensionsPage -Executable $Executable -Uri $Uri }
        ShowGuide = { param($DisplayName, $InstalledRoot, $ChromeExecutable, $WasUpdate) Show-ExtGuideGuidanceWindow -DisplayName $DisplayName -InstalledRoot $InstalledRoot -ChromeExecutable $ChromeExecutable -WasUpdate ([bool] $WasUpdate) }
        ShowError = { param($Failure) Show-ExtGuideFailureWindow -Failure $Failure }
        LogFailure = { param($Failure) Write-ExtGuideSafeLog -Category $Failure.Category }
    }
}


function Set-ExtGuideHostAdapter {
    [CmdletBinding()]
    param([Parameter(Mandatory = $true)][hashtable] $Adapter)
    $script:ExtGuideHostAdapter = $Adapter
}

function Test-ExtGuideHostOperation {
    param([hashtable] $Adapter, [string] $Operation)
    return $Adapter.ContainsKey($Operation) -and $Adapter[$Operation] -is [scriptblock]
}

function Invoke-ExtGuideHostOperation {
    param(
        [Parameter(Mandatory = $true)][hashtable] $Adapter,
        [Parameter(Mandatory = $true)][string] $Operation,
        [object[]] $Arguments = @()
    )
    if (-not (Test-ExtGuideHostOperation -Adapter $Adapter -Operation $Operation)) {
        throw "The Windows host adapter does not provide the '$Operation' operation."
    }
    return & $Adapter[$Operation] @Arguments
}

function Invoke-ExtGuideOptionalHostOperation {
    param(
        [Parameter(Mandatory = $true)][hashtable] $Adapter,
        [Parameter(Mandatory = $true)][string] $Operation,
        [object[]] $Arguments = @(),
        $Default = $null
    )
    if (-not (Test-ExtGuideHostOperation -Adapter $Adapter -Operation $Operation)) { return $Default }
    return & $Adapter[$Operation] @Arguments
}

function Resolve-ExtGuideChrome {
    param([Parameter(Mandatory = $true)][hashtable] $Adapter)

    $running = @(Invoke-ExtGuideHostOperation -Adapter $Adapter -Operation 'GetRunningChromeCandidates')
    $remembered = Invoke-ExtGuideOptionalHostOperation -Adapter $Adapter -Operation 'GetRememberedChrome'
    $registered = @(Invoke-ExtGuideHostOperation -Adapter $Adapter -Operation 'GetRegisteredChromeCandidates')
    $ordered = @($running)
    if (-not [string]::IsNullOrWhiteSpace([string] $remembered)) { $ordered += [string] $remembered }
    $ordered += @($registered)

    $unique = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $valid = @()
    foreach ($candidate in $ordered) {
        if ([string]::IsNullOrWhiteSpace([string] $candidate)) { continue }
        try { $normalized = [System.IO.Path]::GetFullPath([Environment]::ExpandEnvironmentVariables(([string] $candidate).Trim('"'))) }
        catch { continue }
        if (-not $unique.Add($normalized)) { continue }
        if (Invoke-ExtGuideHostOperation -Adapter $Adapter -Operation 'TestChromeSignature' -Arguments @($normalized)) { $valid += $normalized }
    }

    $selected = $null
    if ($valid.Count -eq 1) { $selected = $valid[0] }
    elseif ($valid.Count -gt 1) { $selected = Invoke-ExtGuideOptionalHostOperation -Adapter $Adapter -Operation 'ChooseChrome' -Arguments @(, $valid) -Default $valid[0] }
    else { $selected = Invoke-ExtGuideOptionalHostOperation -Adapter $Adapter -Operation 'ChooseChrome' -Arguments @(, @()) }

    if ([string]::IsNullOrWhiteSpace([string] $selected)) {
        Throw-ExtGuideError -Category 'ChromeDiscovery' -Message 'ExtGuide could not find Google Chrome.' -Recovery 'Install stable Google Chrome, or choose chrome.exe when prompted.'
    }
    $selected = [System.IO.Path]::GetFullPath([string] $selected)
    if (-not (Invoke-ExtGuideHostOperation -Adapter $Adapter -Operation 'TestChromeSignature' -Arguments @($selected))) {
        Throw-ExtGuideError -Category 'ExecutableValidation' -Message 'The selected application is not an authentic stable Google Chrome executable.' -Recovery 'Choose chrome.exe from an official Google Chrome installation.'
    }
    $null = Invoke-ExtGuideOptionalHostOperation -Adapter $Adapter -Operation 'RememberChrome' -Arguments @($selected)
    return $selected
}

function Invoke-ExtGuideBootstrap {
    [CmdletBinding()]
    param([Parameter(Mandatory = $true, Position = 0)][uri] $ManifestUri)

    $adapter = $script:ExtGuideHostAdapter
    try {
        if ($ManifestUri.Scheme -ne 'https') {
            Throw-ExtGuideError -Category 'Configuration' -Message 'The installer manifest URL must use HTTPS.' -Recovery 'Use the HTTPS manifest URL published by the extension author.'
        }
        try { $manifestJson = Invoke-ExtGuideHostOperation -Adapter $adapter -Operation 'FetchText' -Arguments @($ManifestUri) }
        catch {
            if ($null -ne $_.Exception.Data['ExtGuideCategory']) { throw }
            Throw-ExtGuideError -Category 'Network' -Message 'ExtGuide could not download the installer manifest.' -Recovery 'Check the internet connection and verify the manifest URL.' -InnerException $_.Exception
        }
        $manifest = ConvertFrom-ExtGuideManifest -Json $manifestJson

        $localApplicationData = Invoke-ExtGuideHostOperation -Adapter $adapter -Operation 'GetLocalApplicationDataPath'
        $recommended = [System.IO.Path]::Combine($localApplicationData, [string] $manifest.publisher, [string] $manifest.installFolderName)
        $remembered = Invoke-ExtGuideOptionalHostOperation -Adapter $adapter -Operation 'GetRememberedDestination' -Arguments @($manifest)
        if ($remembered) {
            $rememberedExists = Invoke-ExtGuideOptionalHostOperation -Adapter $adapter -Operation 'DestinationExists' -Arguments @([string] $remembered) -Default $false
            if (-not $rememberedExists) { $remembered = $null }
        }
        $choice = Invoke-ExtGuideOptionalHostOperation -Adapter $adapter -Operation 'ChooseDestination' -Arguments @($manifest, $recommended, $remembered) -Default ([pscustomobject]@{ Cancelled = $false; Destination = $recommended; IsCustom = $false })
        if ($choice.Cancelled) { return [pscustomobject]@{ Status = 'Cancelled'; Destination = $recommended } }
        $destination = [System.IO.Path]::GetFullPath([string] $choice.Destination)
        $useElevation = $null -ne $choice.PSObject.Properties['UseElevation'] -and [bool] $choice.UseElevation
        if (-not (Invoke-ExtGuideOptionalHostOperation -Adapter $adapter -Operation 'TestDestinationWritable' -Arguments @($destination) -Default $true) -and -not $useElevation) {
            Throw-ExtGuideError -Category 'Destination' -Message 'The selected installation location is not writable.' -Recovery 'Choose another folder where your Windows account can create and replace files.'
        }

        $hasInlineDigest = $null -ne $manifest.PSObject.Properties['sha256'] -and -not [string]::IsNullOrWhiteSpace([string] $manifest.sha256)
        $expectedSha256 = if ($hasInlineDigest) { ([string] $manifest.sha256).ToLowerInvariant() } else {
            try { ConvertFrom-ExtGuideDigestText -Text (Invoke-ExtGuideHostOperation -Adapter $adapter -Operation 'FetchText' -Arguments @([uri] $manifest.sha256Url)) }
            catch {
                if ($null -ne $_.Exception.Data['ExtGuideCategory']) { throw }
                Throw-ExtGuideError -Category 'Network' -Message 'ExtGuide could not download the archive digest.' -Recovery 'Check the connection or ask the publisher to restore the digest asset.' -InnerException $_.Exception
            }
        }
        try { [byte[]] $archiveBytes = Invoke-ExtGuideHostOperation -Adapter $adapter -Operation 'FetchBytes' -Arguments @([uri] $manifest.archiveUrl) }
        catch {
            if ($null -ne $_.Exception.Data['ExtGuideCategory']) { throw }
            Throw-ExtGuideError -Category 'Network' -Message 'ExtGuide could not download the extension archive.' -Recovery 'Check the connection and retry; the current installation was not changed.' -InnerException $_.Exception
        }
        if ((Get-ExtGuideSha256 -Bytes $archiveBytes) -ne $expectedSha256) {
            Throw-ExtGuideError -Category 'Integrity' -Message 'The downloaded archive does not match its declared SHA-256 digest.' -Recovery 'Do not use this archive. Retry once, then ask the publisher to verify the release digest.'
        }

        $expectedVersion = if ($null -ne $manifest.PSObject.Properties['extensionVersion']) { [string] $manifest.extensionVersion } else { '' }
        $installContext = [pscustomobject]@{
            UseElevation = $useElevation
            IntegrationId = Get-ExtGuideIntegrationId -Manifest $manifest
            Publisher = [string] $manifest.publisher
            InstallFolderName = [string] $manifest.installFolderName
            ArchiveSha256 = $expectedSha256
            ExpectedVersion = $expectedVersion
        }
        while ($true) {
            try {
                $installation = Invoke-ExtGuideHostOperation -Adapter $adapter -Operation 'WriteExtension' -Arguments @($archiveBytes, $destination, $manifest.extensionRoot, $installContext)
                break
            }
            catch {
                if (-not [bool] $_.Exception.Data['ExtGuideElevationDeclined']) { throw }
                $fallbackChoice = Invoke-ExtGuideOptionalHostOperation -Adapter $adapter -Operation 'ChooseFallbackDestination' -Arguments @($manifest)
                if ($null -eq $fallbackChoice) {
                    $null = Invoke-ExtGuideOptionalHostOperation -Adapter $adapter -Operation 'CloseInstallSession' -Arguments @([string] $manifest.displayName)
                    return [pscustomobject]@{ Status = 'Cancelled'; Destination = $destination }
                }
                if ($null -ne $fallbackChoice.PSObject.Properties['Destination']) {
                    $destination = [System.IO.Path]::GetFullPath([string] $fallbackChoice.Destination)
                    $installContext.UseElevation = $null -ne $fallbackChoice.PSObject.Properties['UseElevation'] -and [bool] $fallbackChoice.UseElevation
                }
                else {
                    $destination = [System.IO.Path]::GetFullPath([string] $fallbackChoice)
                    $installContext.UseElevation = $false
                }
                if (-not (Invoke-ExtGuideOptionalHostOperation -Adapter $adapter -Operation 'TestDestinationWritable' -Arguments @($destination) -Default $true) -and -not [bool] $installContext.UseElevation) {
                    Throw-ExtGuideError -Category 'Destination' -Message 'The replacement installation location is not writable.' -Recovery 'Choose another folder or request administrator permission.'
                }
            }
        }
        $null = Invoke-ExtGuideOptionalHostOperation -Adapter $adapter -Operation 'RememberDestination' -Arguments @($manifest, $destination)
        $chromeExecutable = Resolve-ExtGuideChrome -Adapter $adapter
        $installedRoot = $installation.ExtensionRoot
        try { $null = Invoke-ExtGuideHostOperation -Adapter $adapter -Operation 'SetClipboard' -Arguments @($installedRoot) }
        catch { Throw-ExtGuideError -Category 'Launch' -Message 'ExtGuide could not copy the extension path.' -Recovery 'Copy the displayed extension path manually.' -InnerException $_.Exception }

        $extensionsUri = 'chrome://extensions/'
        try { $null = Invoke-ExtGuideHostOperation -Adapter $adapter -Operation 'LaunchChrome' -Arguments @($chromeExecutable, $extensionsUri) }
        catch { Throw-ExtGuideError -Category 'Launch' -Message 'ExtGuide installed the extension but could not open Chrome.' -Recovery 'Open Google Chrome and navigate to chrome://extensions manually.' -InnerException $_.Exception }
        $guide = Invoke-ExtGuideHostOperation -Adapter $adapter -Operation 'ShowGuide' -Arguments @($manifest.displayName, $installedRoot, $chromeExecutable, [bool] $installation.WasUpdate)

        return [pscustomobject]@{
            Status = $guide.State
            Destination = $destination
            InstalledRoot = $installedRoot
            InstalledContent = $installation.Content
            WasUpdate = [bool] $installation.WasUpdate
            PreviousVersion = if ($null -ne $installation.PSObject.Properties['PreviousVersion']) { [string] $installation.PreviousVersion } else { '' }
            InstalledVersion = if ($null -ne $installation.PSObject.Properties['InstalledVersion']) { [string] $installation.InstalledVersion } else { '' }
            ClipboardPath = $installedRoot
            ChromeExecutable = $chromeExecutable
            LaunchUri = $extensionsUri
            Guide = $guide
        }
    }
    catch {
        $failure = ConvertTo-ExtGuideFailure -ErrorRecord $_
        $null = Invoke-ExtGuideOptionalHostOperation -Adapter $adapter -Operation 'LogFailure' -Arguments @($failure)
        $null = Invoke-ExtGuideOptionalHostOperation -Adapter $adapter -Operation 'ShowError' -Arguments @($failure)
        return $failure
    }
}


$script:ExtGuideHostAdapter = New-ExtGuideWindowsHostAdapter

Invoke-ExtGuideBootstrap -ManifestUri $ManifestUri